/* Теория боевой системы. Подключается в index.html отдельным файлом. */

var MARTIAL_THEORY = [
['Стойка, дыхание, центр тяжести','ПОЧЕМУ ЭТО ОБЩЕЕ ДЛЯ ВСЕХ СИСТЕМ ПРОГРАММЫ\nБокс, муай-тай, дуаньда, система Кадочникова и самбо технически различаются радикально, но опираются на одну физическую основу: устойчивое положение тела, из которого можно быстро двигаться, и дыхание, не мешающее этому движению.\n\nБАЗОВАЯ СТОЙКА\nНоги на ширине плеч или чуть шире, колени слегка согнуты, вес распределён равномерно или слегка смещён на заднюю ногу, корпус развёрнут под небольшим углом, подбородок слегка прижат.\n\nЦЕНТР ТЯЖЕСТИ И ЕГО РОЛЬ\nНаходится на уровне двух-трёх пальцев ниже пупка. Чем ниже он опущен за счёт сгибания коленей, тем труднее вывести человека из равновесия — это напрямую используется в системе Кадочникова и в самбо.\n\nДИНАМИЧЕСКАЯ, А НЕ СТАТИЧНАЯ УСТОЙЧИВОСТЬ\nСтойка — не неподвижная поза, а готовность сдвинуть центр тяжести в любую сторону. Излишне жёсткая стойка легче выводится из равновесия импульсом, поскольку не может подстроиться под направление силы.\n\nДИАФРАГМАЛЬНОЕ ДЫХАНИЕ\nДыхание животом снижает напряжение в плечевом поясе и даёт более стабильный приток кислорода при нагрузке, чем поверхностное грудное дыхание.\n\nСВЯЗЬ ДЫХАНИЯ С УДАРОМ\nРезкий выдох в момент удара синхронизирует напряжение мышц кора с моментом контакта и защищает внутренние органы от встречного удара.\n\nДЫХАНИЕ КАК ИНСТРУМЕНТ КОНТРОЛЯ СОСТОЯНИЯ\nВ системе Кадочникова и в дуаньда дыхание используется для управления уровнем возбуждения нервной системы — задержка дыхания от напряжения ускоряет утомление и ухудшает координацию.\n\nПЕРЕНОС ВЕСА КАК ОСНОВА ПЕРЕМЕЩЕНИЯ\nДвижение начинается с переноса центра тяжести, нога лишь следует за уже начавшимся смещением веса — обратный порядок даёт заметную заминку.\n\nОТРАБОТКА БЕЗ ПАРТНЁРА\nВсе элементы темы полностью осваиваются в одиночку перед зеркалом и самостоятельными пробами на равновесие.\n\nТИПИЧНЫЕ ОШИБКИ\nСлишком широкая или узкая стойка; поднятые плечи при вдохе; задержка дыхания при напряжении; шаг раньше переноса веса; излишне жёсткая фиксация стойки.\n\nПРОВЕРЬ СЕБЯ\n1. Почему устойчивость должна быть динамической?\n2. Где находится центр тяжести и как влияет на устойчивость?\n3. Чем диафрагмальное дыхание лучше грудного?\n4. Зачем делается выдох на ударе?\n5. С чего начинается перемещение в стойке?'],
['Разминка и подготовка суставов','ЗАЧЕМ РАЗМИНКА ИМЕННО ПЕРЕД ЭТИМИ СИСТЕМАМИ\nПрограмма сочетает резкие удары с работой на грани подвижности суставов (болевые самбо, растяжка для высоких ударов) — требует более тщательной подготовки, чем каждая дисциплина по отдельности.\n\nОБЩАЯ РАЗМИНКА\nПовышение температуры тела и учащение пульса пять-семь минут — холодная мышца рвётся легче нагретой, пропуск этого этапа частая причина травм.\n\nСУСТАВНАЯ ГИМНАСТИКА\nПроработка каждого сустава от периферии к центру, особое внимание кистям (бокс) и голеностопам (удары ногой, броски).\n\nПОДГОТОВКА ДЛЯ УДАРНОЙ ЧАСТИ\nПлечи и корпус разминаются отдельно, поскольку сила удара передаётся ротацией корпуса — холодные косые мышцы легко растягиваются при резком ударе.\n\nПОДГОТОВКА ДЛЯ БРОСКОВОЙ И БОЛЕВОЙ ЧАСТИ\nЛучезапястные, локтевые суставы и поясница требуют внимания, поскольку партнёр не всегда точно чувствует предел вашей подвижности.\n\nДИНАМИЧЕСКАЯ РАСТЯЖКА ПЕРЕД ТРЕНИРОВКОЙ\nАктивные махи без задержки в крайней точке готовят мышцу к работе, не снижая взрывную силу.\n\nСТАТИЧЕСКАЯ РАСТЯЖКА ПОСЛЕ ТРЕНИРОВКИ\nУдержание позиции пятнадцать-тридцать секунд в конце занятия — временно снижает взрывную силу, поэтому не делается перед ударной работой.\n\nПОДГОТОВКА УДАРНЫХ ПОВЕРХНОСТЕЙ\nГолень и костяшки требуют постепенной адаптации через дозированную работу по мешку — удар в полную силу без месяцев подготовки повреждает надкостницу.\n\nПРИЗНАКИ НЕДОСТАТОЧНОЙ РАЗМИНКИ\nСкованность в суставе, боль вместо обычного напряжения, холодные конечности — сигнал отложить интенсивную часть.\n\nТИПИЧНЫЕ ОШИБКИ\nПропуск общей разминки; статическая растяжка перед ударной тренировкой; работа в полный контакт без адаптации; недостаточное внимание суставам бросковой части.\n\nПРОВЕРЬ СЕБЯ\n1. Почему холодная мышца рвётся легче?\n2. Каким суставам уделять внимание перед ударной частью?\n3. Чем динамическая растяжка отличается от статической по цели?\n4. Почему нельзя сразу бить в полную силу?\n5. Какие признаки недостаточной разминки?'],
['Падения и самостраховка (укеми)','ПОЧЕМУ ЭТО РАНЬШЕ БРОСКОВ\nПрежде чем изучать броски, нужно уметь безопасно упасть — без этого навыка бросковая тренировка становится источником травм. Укеми — искусство контролируемого падения.\n\nПРИНЦИП РАСПРЕДЕЛЕНИЯ УДАРА\nЭнергия падения гасится не одной точкой, а хлопком всей рукой или боком одновременно с приземлением — распределяет силу на большую площадь.\n\nПАДЕНИЕ НА СПИНУ\nПодбородок прижат к груди — предотвращает удар затылком. Руки хлопают под углом сорок пять градусов, ноги слегка согнуты. Отработка от минимальной высоты.\n\nПАДЕНИЕ НА БОК\nПодбородок прижат, хлопок рукой перпендикулярно телу, нога первой касается поверхности, голова не касается земли.\n\nПАДЕНИЕ ВПЕРЁД\nКонтакт через предплечья при почти горизонтальном положении корпуса с перекатом через плечо — прямое падение на живот опаснее для позвоночника и дыхания.\n\nКУВЫРОК КАК ПОДГОТОВИТЕЛЬНОЕ УПРАЖНЕНИЕ\nОбычный гимнастический кувырок готовит к специализированным падениям, тренируя тот же навык переката энергии.\n\nПОСТЕПЕННОСТЬ КАК ОБЯЗАТЕЛЬНОЕ ПРАВИЛО\nОтработка идёт от сидя к полуприседу, к стоя, к падению как реакции на реальный бросок — перепрыгивание этапов ведёт к травме.\n\nСАМОСТОЯТЕЛЬНАЯ ОТРАБОТКА\nНачальные и средние этапы доступны в одиночку на мате — партнёр нужен только для падения как реакции на реальный бросок.\n\nСВЯЗЬ С ОСТАЛЬНОЙ ПРОГРАММОЙ\nУверенное укеми — предварительное условие для модулей с бросками, иначе партнёр вынужден действовать неполноценно или рискует вашей безопасностью.\n\nТИПИЧНЫЕ ОШИБКИ\nПадение с высоты роста без постепенности; недостаточно прижатый подбородок; жёсткое приземление локтем вместо хлопка; переход к реальным броскам до освоения самостоятельной версии.\n\nПРОВЕРЬ СЕБЯ\n1. За счёт чего гасится энергия падения?\n2. Почему подбородок должен быть прижат?\n3. Чем падение вперёд с перекатом безопаснее падения на живот?\n4. Как кувырок связан с борцовскими падениями?\n5. Когда становится необходим партнёр?'],
['Техника безопасности при парной работе','ЗАЧЕМ ЭТОТ РАЗДЕЛ\nБроски, болевые, удушения, клинч требуют партнёра и не заменяются одиночной практикой — раздел описывает, как организовать парную тренировку без зала и тренера.\n\nСИГНАЛ ОСТАНОВКИ\nЧёткий, заранее согласованный сигнал (хлопок, слово) — получивший обязан остановить действие мгновенно, без промедления на "ещё чуть-чуть".\n\nГРАДАЦИЯ РЕАЛИЗМА\nОт полностью пассивного партнёра к лёгкому сопротивлению и лишь затем к свободному взаимодействию — пропуск ступеней основная причина травм при самостоятельных занятиях.\n\nКОНТРОЛЬ СИЛЫ КАК ОТДЕЛЬНЫЙ НАВЫК\nСпособность применить приём достаточно для техники, но не для травмы — требует практики, разумно систематически недооценивать силу вначале.\n\nОСОБАЯ ОСТОРОЖНОСТЬ С БОЛЕВЫМИ И УДУШАЮЩИМИ\nБолевой приём травмирует почти мгновенно после предела подвижности без предупреждения. Удушение опасно тем, что потеря сознания наступает быстрее сигнала остановки — эта категория наименее подходит для полностью самостоятельного освоения без старшего наблюдателя.\n\nНЕОБХОДИМОЕ ОСНАЩЕНИЕ\nТолстый борцовский мат обязателен для бросковой работы — тренировка на голом полу создаёт неприемлемый риск даже при правильной технике.\n\nПСИХОЛОГИЧЕСКАЯ ГОТОВНОСТЬ И ЭГО\nСоревновательное желание не поддаться на этапе отработки техники разрушает цель упражнения и повышает риск травмы для обоих.\n\nФИКСАЦИЯ ДОГОВОРЁННОСТЕЙ\nПеред каждой сессией проговаривать, что отрабатывается, на каком уровне реализма, и напомнить сигнал остановки.\n\nТИПИЧНЫЕ ОШИБКИ\nОтсутствие сигнала остановки; пропуск ступеней градации реализма; отработка бросков без защитного покрытия; соревновательное сопротивление на этапе постановки техники; самостоятельная практика удушений без наблюдателя.\n\nПРОВЕРЬ СЕБЯ\n1. Каким должен быть сигнал остановки?\n2. Из каких ступеней состоит градация реализма?\n3. Почему контроль силы отдельный навык?\n4. Чем удушения опаснее болевых по времени реакции?\n5. Что проговаривать перед парной тренировкой?'],
['Стойка и передвижение бокса','БОКСЁРСКАЯ СТОЙКА КАК СПЕЦИАЛИЗАЦИЯ ОБЩЕЙ СТОЙКИ\nБазовая стойка из первого модуля здесь принимает специфическую форму: для правши левая нога и левая рука впереди, сильная правая — сзади для акцентированного удара. Ступни развёрнуты примерно на сорок пять градусов.\n\nПОЛОЖЕНИЕ РУК В СТОЙКЕ\nПодбородок спрятан за плечо передней руки, кулаки на уровне скул, локти прижаты к корпусу — разведённые локти открывают корпус для удара по рёбрам и печени.\n\nРАСПРЕДЕЛЕНИЕ ВЕСА\nВес распределён поровну или с небольшим смещением на заднюю ногу — исходная точка, из которой вес постоянно смещается в зависимости от действия.\n\nШАГ КАК ЕДИНИЦА ПЕРЕДВИЖЕНИЯ\nКороткие приставные шаги: нога в направлении движения идёт первой, вторая подтягивается следом. Скрещивание ног — грубая ошибка, временно лишающая устойчивости.\n\nЧЕТЫРЕ БАЗОВЫХ НАПРАВЛЕНИЯ\nВперёд — передней ногой, назад — задней, в сторону — ногой с той же стороны, вторая нога всегда подтягивается следом.\n\nЦИРКУЛЯРНОЕ ПЕРЕДВИЖЕНИЕ\nДвижение по дуге вокруг соперника позволяет менять угол атаки, заходя сбоку, вместо предсказуемого прямолинейного сближения.\n\nСВЯЗЬ С ДЫХАНИЕМ И ЦЕНТРОМ ТЯЖЕСТИ\nПеремещение начинается с переноса центра тяжести, а не с движения ногой — обратный порядок даёт заметную задержку, которую соперник использует для упреждающего удара.\n\nСАМОСТОЯТЕЛЬНАЯ ОТРАБОТКА\nСтойка и передвижение полностью отрабатываются в одиночку перед зеркалом и в тени.\n\nТИПИЧНЫЕ ОШИБКИ\nРазведённые локти; скрещивание ног при передвижении; слишком широкая или узкая стойка; неприкрытый подбородок; движение только по прямым линиям.\n\nПРОВЕРЬ СЕБЯ\n1. Как располагаются руки и ноги в стойке правши?\n2. Почему разведённые локти — ошибка?\n3. Как устроено приставное передвижение?\n4. Зачем нужно циркулярное передвижение?\n5. Что из стойки и передвижения отрабатывается без партнёра?'],
['Четыре базовых удара','ДЖЕБ: БЫСТРЫЙ УДАР ПЕРЕДНЕЙ РУКОЙ\nПрямой удар с минимальным замахом, самый частый удар для контроля дистанции и разведки, задняя рука остаётся у подбородка.\n\nКРОСС: АКЦЕНТИРОВАННЫЙ УДАР ЗАДНЕЙ РУКОЙ\nИспользует ротацию бёдер и корпуса как основной источник силы — задняя пятка отрывается и разворачивается, передавая усилие в кулак.\n\nХУК: БОКОВОЙ УДАР\nДугообразная траектория, локоть согнут под прямым углом. Сила создаётся ротацией стопы, колена и бедра — без вращения нижней части тела удар заметно слабее.\n\nАППЕРКОТ: УДАР СНИЗУ ВВЕРХ\nКолени сгибаются перед ударом и распрямляются в момент нанесения, добавляя усилие от ног к ротации корпуса.\n\nОБЩИЙ ПРИНЦИП: КИНЕТИЧЕСКАЯ ЦЕПЬ\nИмпульс от ног, затем бёдра, корпус, плечо, и лишь затем рука — разрыв цепи в любом звене резко снижает силу удара.\n\nВОЗВРАТ РУКИ ПОСЛЕ УДАРА\nРука возвращается в защитное положение сразу после удара — задержка в вытянутом положении открывает лицо для встречного удара.\n\nПОСЛЕДОВАТЕЛЬНОСТЬ ОСВОЕНИЯ\nМедленный темп без снаряда перед зеркалом, затем лапы или мешок с лёгким контактом, затем полная скорость.\n\nСАМОСТОЯТЕЛЬНАЯ ОТРАБОТКА\nВсе четыре удара полностью осваиваются на мешке и в тени.\n\nТИПИЧНЫЕ ОШИБКИ\nУдар без ротации бёдер; задержка руки после удара; хук по прямой траектории; апперкот без работы коленей.\n\nПРОВЕРЬ СЕБЯ\n1. Чем джеб отличается от кросса по назначению?\n2. Что является источником силы кросса помимо руки?\n3. Почему хук без ротации стопы слабее?\n4. Что такое кинетическая цепь?\n5. Почему рука должна немедленно возвращаться в защиту?'],
['Защита руками и корпусом','ПРИНЦИП: НЕ КАЖДЫЙ УДАР НУЖНО БЛОКИРОВАТЬ\nЗащита строится на наборе решений: блок, уход корпусом, контроль дистанции — опора только на блоки делает защиту предсказуемой.\n\nБЛОК ЛАДОНЬЮ И ПРЕДПЛЕЧЬЕМ\nПрямые удары останавливаются мягким, поддающимся движением руки — жёсткий блок передаёт больше энергии в собственную руку и корпус.\n\nБЛОК ЛОКТЕМ ОТ УДАРОВ ПО КОРПУСУ\nХуки и апперкоты в корпус останавливаются прижатым локтем и предплечьем.\n\nНЫРОК (ДАКИНГ)\nУход от хука сгибанием ног и наклоном корпуса, а не только шеи — наклон одной шеей ограничивает амплитуду и рискует травмой.\n\nУКЛОН (СЛИП)\nСмещение головы от траектории прямого удара без глубокого сгибания ног — требует точной оценки дистанции.\n\nПАРИРОВАНИЕ\nЛёгкое отклонение траектории удара кистью вместо полного блока — требует меньше усилий и может вывести соперника из равновесия.\n\nКОНТРОЛЬ ДИСТАНЦИИ КАК ФОРМА ЗАЩИТЫ\nПоддержание дистанции, на которой удар не достаёт без шага, — самая энергоэффективная защита.\n\nСАМОСТОЯТЕЛЬНАЯ ОТРАБОТКА\nБазовая механика каждого движения отрабатывается перед зеркалом на воображаемую атаку до перехода к реальному партнёру.\n\nТИПИЧНЫЕ ОШИБКИ\nЖёсткий блок вместо мягкого; нырок одной шеей; недостаточная амплитуда уклона; игнорирование контроля дистанции.\n\nПРОВЕРЬ СЕБЯ\n1. Почему опора только на блоки делает защиту предсказуемой?\n2. Чем жёсткий блок хуже мягкого?\n3. Чем нырок отличается от уклона?\n4. Что такое парирование?\n5. Почему контроль дистанции самая энергоэффективная защита?'],
['Комбинации и работа на мешке','ОТ ОДИНОЧНОГО УДАРА К СВЯЗКЕ\nЭффективность определяется способностью соединять удары, где каждый следующий использует позицию тела после предыдущего.\n\nБАЗОВЫЕ ДВУХУДАРНЫЕ СВЯЗКИ\nДжеб-кросс — простейшая связка. Кросс-хук использует ротацию первого удара как начало ротации второго.\n\nТРЁХ- И ЧЕТЫРЁХУДАРНЫЕ СВЯЗКИ\nКаждый удар должен логично продолжать позицию после предыдущего — полный возврат в нейтральную стойку между ударами теряет темп и силу.\n\nСМЕНА УРОВНЯ АТАКИ\nЧередование ударов по голове и корпусу заставляет менять защиту по вертикали, создавая больше возможностей для пропуска.\n\nРИТМ И ПАУЗЫ МЕЖДУ СВЯЗКАМИ\nСвязка не должна выполняться в одном ритме каждый раз — на мешке это означает сознательное чередование быстрых серий и медленных одиночных ударов.\n\nРАБОТА НА МЕШКЕ: ЦЕЛИ ЗАНЯТИЯ\nМешок даёт реальное сопротивление и обратную связь по силе, развивает силовую выносливость плечевого пояса для серии ударов.\n\nРАУНДОВАЯ СТРУКТУРА\nРаунды по две-три минуты с минутой отдыха, воспроизводящие структуру реального боя, с постепенным увеличением числа раундов.\n\nЧЕРЕДОВАНИЕ ЗАДАЧ ВНУТРИ РАУНДА\nОтдельные раунды на технику одиночных ударов, на связки в темпе, на максимальную скорость, на защитные перемещения.\n\nТИПИЧНЫЕ ОШИБКИ\nВозврат в нейтральную стойку между ударами связки; атака только на одном уровне; механическое повторение в одном темпе; работа без раундовой структуры.\n\nПРОВЕРЬ СЕБЯ\n1. Почему связка эффективнее изолированных ударов?\n2. Какая ошибка разрушает непрерывность длинных связок?\n3. Зачем чередовать удары по голове и корпусу?\n4. Почему связку нельзя выполнять в одном ритме?\n5. Как распределить задачи между раундами на мешке?'],
['Принципы противодействия группе','ГРУППА ОПАСНЕЕ АРИФМЕТИЧЕСКОЙ СУММЫ ПРОТИВНИКОВ\nПризнанный во всех серьёзных системах прикладной самообороны принцип, включая работы Рори Миллера и Джеффа Томпсона: столкновение с двумя противниками качественно, а не в два раза опаснее, поскольку добавляется направление, с которого невозможно наблюдать одновременно со всеми остальными.\n\nЭФФЕКТ ОКРУЖЕНИЯ\nЕсли противники расходятся под углом более девяноста градусов друг к другу, вы физически не можете держать в поле зрения обоих без поворота головы, а поворот на долю секунды открывает противоположную сторону.\n\nРАЗДЕЛЕНИЕ ВНИМАНИЯ И КОГНИТИВНАЯ ПЕРЕГРУЗКА\nВнимание не способно эффективно отслеживать намерения нескольких независимо действующих людей одновременно — подтверждено исследованиями психологии внимания.\n\nРИСК УДАРА СО СПИНЫ КАК ГЛАВНАЯ УГРОЗА\nБольшинство серьёзных травм в задокументированных случаях группового нападения происходит от удара вне поля зрения жертвы — это определяет главный приоритет: контроль позиции важнее контроля конкретного противника.\n\nПОЧЕМУ НЕЛЬЗЯ ПРИМЕНЯТЬ ТАКТИКУ ПОЕДИНКА ОДИН НА ОДИН\nПродолжительный обмен ударами или работа в партере против группы опасны, поскольку каждая секунда с одним противником даёт остальным время беспрепятственно приблизиться.\n\nПРЕДВАРИТЕЛЬНОЕ РАСПОЗНАВАНИЕ УГРОЗЫ ГРУППЫ\nПризнанные системы учат распознавать признаки надвигающегося нападения до его начала: изменение построения группы, синхронизация движения, предконфликтные провокации.\n\nГОЛОС И ПОЗИЦИЯ КАК ПЕРВАЯ ЛИНИЯ\nПодход Тони Блауэра (система SPEAR) подчёркивает важность вербального контроля и заблаговременного позиционирования прежде физической тактики.\n\nОТСУТСТВИЕ УНИВЕРСАЛЬНОЙ ТЕХНИКИ ПРОТИВ ГРУППЫ\nЧестная оговорка всех серьёзных источников: не существует техники, гарантированно побеждающей нескольких решительных противников — материал снижает риск, но не отменяет объективную опасность ситуации.\n\nТИПИЧНЫЕ ОШИБКИ\nУдержание одного противника длительным контролем при наличии рядом других; поворот спиной к части группы; недооценка ранних признаков конфликта; вера в универсальную технику.\n\nПРОВЕРЬ СЕБЯ\n1. Почему конфликт с двумя противниками качественно опаснее конфликта с одним?\n2. Что такое эффект окружения?\n3. Откуда происходит большинство травм в групповых нападениях?\n4. Почему партер особенно противопоказан против группы?\n5. Какую оговорку признают все серьёзные источники?'],
['Использование пространства и препятствий','ПРОСТРАНСТВО КАК АКТИВНЫЙ ИНСТРУМЕНТ\nПри столкновении с группой управление позицией в пространстве равноценно по важности физической технике — правильная позиция нейтрализует численное превосходство.\n\nСПИНА К СТЕНЕ КАК БАЗОВЫЙ ПРИНЦИП\nПозиция спиной к стене устраняет возможность атаки с этого направления, сокращая число направлений угрозы с трёхсот шестидесяти градусов до контролируемого сектора.\n\nДВЕРНОЙ ПРОЁМ КАК ОГРАНИЧИТЕЛЬ ЧИСЛА АТАКУЮЩИХ\nУзкий проход физически ограничивает число одновременно контактирующих противников до одного-двух, превращая столкновение с группой в последовательность управляемых поединков.\n\nИСПОЛЬЗОВАНИЕ ОДНОГО ПРОТИВНИКА КАК ПРЕПЯТСТВИЯ\nМанипулирование положением ближайшего противника так, чтобы его тело оказалось между вами и остальными, создаёт секунды для манёвра или отхода.\n\nДВИЖУЩАЯСЯ, А НЕ СТАТИЧНАЯ ПОЗИЦИЯ\nПостоянное перемещение вынуждает противников оказываться на линии друг с другом, либо перестраиваться, теряя время, либо мешать друг другу.\n\nОБЪЕКТЫ ОКРУЖЕНИЯ КАК ИНСТРУМЕНТ ЗАМЕДЛЕНИЯ\nМебель и препятствия между вами и группой замедляют продвижение и дают время на решение или отход.\n\nОСВЕЩЕНИЕ И ВИДИМОСТЬ КАК ФАКТОР\nПозиционирование так, чтобы источник света был позади вас, улучшает вашу видимость противников и ухудшает их оценку ваших движений.\n\nОТРАБОТКА БЕЗ ПАРТНЁРА\nМысленная или физическая прогулка по реальным пространствам с вопросом о выгодной позиции — прямая рекомендация литературы по ситуационной осведомлённости, не требует партнёра.\n\nТИПИЧНЫЕ ОШИБКИ\nНемедленное физическое взаимодействие без позиционирования; статичное укрытие вместо динамики; игнорирование проёмов как ограничителя; недооценка мебели как инструмента замедления.\n\nПРОВЕРЬ СЕБЯ\n1. Почему спина к стене — базовый принцип?\n2. Как дверной проём ограничивает число атакующих?\n3. Как использовать тело противника как препятствие?\n4. Чем движущаяся позиция выгоднее статичной?\n5. Какое упражнение по осведомлённости отрабатывается без партнёра?'],
['Приоритет отхода над боем','УХОД КАК ПРЕВОСХОДЯЩЕЕ РЕШЕНИЕ\nЦентральный принцип литературы по самообороне: если уход возможен, он статистически превосходит вступление в бой независимо от уровня подготовки.\n\nАСИММЕТРИЯ РИСКА\nПобеда в бою с группой не устраняет риск травмы даже для победителя, тогда как успешный уход устраняет риск почти полностью.\n\nРАСПОЗНАВАНИЕ МОМЕНТА, ПОКА УХОД ВОЗМОЖЕН\nВозможность уйти убывает с каждой секундой промедления — решение принимается на ранней стадии, пока путь ещё свободен.\n\nПСИХОЛОГИЧЕСКИЕ ПРЕПЯТСТВИЯ К ОТХОДУ\nСтрах показаться трусом, ложное ощущение провокации преследования, гнев — барьеры, осознание которых заранее снижает их влияние в реальный момент.\n\nОТХОД НЕ ОЗНАЧАЕТ БЕЗДЕЙСТВИЕ\nРешение уйти не отменяет контроль позиции и дистанции, а также краткое действие, создающее возможность отхода.\n\nКОГДА ОТХОД НЕВОЗМОЖЕН ИЛИ НЕПРИЕМЛЕМ\nОкружение завершено или необходимость защитить неспособного передвигаться человека — приоритет смещается к тактике невозможности отступления.\n\nПРАВОВОЙ АСПЕКТ\nДемонстрируемая попытка избежать конфликта усиливает правовую позицию самообороны в большинстве юрисдикций.\n\nОТРАБОТКА РЕШЕНИЯ КАК НАВЫКА\nСпособность быстро решить уйти тренируется ментальной репетицией сценария заранее принятого решения.\n\nТИПИЧНЫЕ ОШИБКИ\nВосприятие ухода как слабости; промедление до перекрытия пути; полная пассивность вместо контроля по пути отхода; игнорирование правового аспекта.\n\nПРОВЕРЬ СЕБЯ\n1. Почему уход превосходит победу в бою по риску?\n2. Что такое асимметрия риска?\n3. Какие психологические барьеры мешают отходу?\n4. Означает ли решение уйти полную пассивность?\n5. Как попытка избежать конфликта усиливает правовую позицию?'],
['Тактика при невозможности отступления','КОГДА ЭТОТ РАЗДЕЛ ПРИМЕНИМ\nМатериал вступает в действие только когда путь к отходу физически отрезан — логическое продолжение приоритета отхода, а не альтернатива ему.\n\nПРИНЦИП: ОДИН ПРОТИВНИК ЗА РАЗ\nАктивное перемещение так, чтобы взаимодействовать с минимальным числом противников одновременно, используя остальных как препятствие друг для друга.\n\nДВИЖЕНИЕ ПО КРУГУ ВОКРУГ БЛИЖАЙШЕГО ПРОТИВНИКА\nПеремещение вокруг оси ближайшего так, чтобы он оставался между вами и остальными, требует постоянного контроля всех видимых противников.\n\nВЫБОР ЦЕЛИ: БЛИЖАЙШАЯ И НАИБОЛЕЕ АКТИВНАЯ УГРОЗА\nПриоритет — не самому опасному внешне, а физически ближайшему с непосредственными признаками готовности к действию, оценка непрерывна.\n\nБЫСТРОЕ ДЕЙСТВИЕ ВМЕСТО ЗАТЯЖНОГО ВЗАИМОДЕЙСТВИЯ\nКаждое взаимодействие максимально короткое — цель не техническое превосходство, а быстрое переключение внимания на общую картину.\n\nПРИМЕНЕНИЕ УДАРНОЙ ТЕХНИКИ БЕЗ ЗАТЯЖНОГО КОНТАКТА\nКороткие серии для создания пространства, а не развёрнутый обмен ударами спортивного поединка.\n\nИЗБЕГАНИЕ ЗАХВАТОВ И ПРОДОЛЖИТЕЛЬНОГО КОНТРОЛЯ\nБроски и болевые применяются только в сокращённой форме для мгновенной дестабилизации — время на чистое исполнение здесь уязвимость.\n\nСОХРАНЕНИЕ ПОЗИЦИИ КАК ПОСТОЯННАЯ ЗАДАЧА\nТехническое взаимодействие не должно происходить за счёт полной потери контроля над положением остальных.\n\nПОСТОЯННЫЙ ПОИСК ВОЗОБНОВИВШЕЙСЯ ВОЗМОЖНОСТИ ОТХОДА\nСитуация может измениться в процессе — доступность отхода переоценивается непрерывно, а не считается решённой однократно.\n\nТИПИЧНЫЕ ОШИБКИ\nСосредоточение на техническом совершенстве в ущерб контролю позиции; попытка полного броска вместо короткого действия; выбор цели по субъективной опасности вместо близости; отказ от переоценки возможности отхода.\n\nПРОВЕРЬ СЕБЯ\n1. При каком условии применяется этот раздел?\n2. В чём смысл движения по кругу вокруг ближайшего противника?\n3. По какому критерию выбирается цель?\n4. Почему затяжной приём противопоказан здесь?\n5. Пересматривается ли решение о невозможности отхода в ходе конфликта?'],
['Стрессовая реакция организма в конфликте','ПОЧЕМУ ЭТО ОТДЕЛЬНЫЙ ОБЯЗАТЕЛЬНЫЙ РАЗДЕЛ\nТехника ставится в спокойных условиях тренировки, но реальный конфликт запускает физиологическую реакцию, качественно меняющую её исполнение. Исследования Дэйва Гроссмана ("On Combat") и Брюса Сиддла (PPCT) стали стандартом подготовки полиции и армии по всему миру именно потому, что объясняют разрыв между тренировочной и реальной эффективностью.\n\nВЫБРОС АДРЕНАЛИНА И ЕГО ЭФФЕКТЫ\nУчащение сердечного ритма, перенаправление кровотока от кистей и стоп к крупным мышцам. Похолодание и потеря мелкой моторики в пальцах — не слабость, а задокументированное физиологическое следствие.\n\nРЕАКЦИЯ БЕЙ-БЕГИ-ЗАМРИ\nКлассическая триада: схватка, бегство или полное замирание при оценке ситуации как безнадёжной. Замирание задокументировано как частая, а не редкая реакция даже у подготовленных людей.\n\nПОТЕРЯ МЕЛКОЙ МОТОРИКИ\nПри частоте сердечных сокращений значительно выше покоя способность к тонким движениям пальцев резко падает, крупные взрывные движения остаются сохранными — обоснование выбора крупномоторной техники в этой программе.\n\nВРЕМЕННОЕ СНИЖЕНИЕ БОЛЕВОЙ ЧУВСТВИТЕЛЬНОСТИ\nСтресс-индуцированная анальгезия — отсутствие болевой реакции противника не всегда означает промах или слабый удар.\n\nТРЕНИРОВКА КАК СПОСОБ СМЕЩЕНИЯ ПОРОГА\nРеалистичная тренировка под контролируемым нарастающим стрессом смещает порог дезорганизации выше — натренированный человек сохраняет функциональность при более высоком возбуждении, хотя полностью устранить эффект нельзя.\n\nСВЯЗЬ С ВЫБОРОМ ТЕХНИКИ КУРСА\nПриоритет быстрых, грубых действий над тонкой техникой в разделе о нескольких противниках прямо соответствует этой физиологии.\n\nТИПИЧНЫЕ ОШИБКИ\nИнтерпретация похолодания рук как личной слабости; техническая база на тонкой моторике без учёта стресса; недооценка замирания как редкой реакции; вывод об отсутствии эффекта удара по отсутствию видимой боли.\n\nПРОВЕРЬ СЕБЯ\n1. Кто стоит за современным пониманием стрессовой реакции в подготовке силовых структур?\n2. Что происходит с кровотоком к кистям при остром стрессе?\n3. Что такое реакция замирания?\n4. Почему техника курса опирается на крупномоторные движения?\n5. Как тренировка влияет на порог дезорганизации реакции?'],
['Тоннельное зрение и звуковое исключение','ДВА СВЯЗАННЫХ ЭФФЕКТА\nОстрый стресс вызывает сужение поля зрения и частичную потерю слуха — оба задокументированы в психологии стресса и в сообщениях участников реальных конфликтов, собранных Гроссманом.\n\nМЕХАНИЗМ ТОННЕЛЬНОГО ЗРЕНИЯ\nВнимание фокусируется на источнике угрозы настолько интенсивно, что периферия перестаёт обрабатываться сознанием — заметить второго нападающего значительно труднее, даже если он физически виден.\n\nМЕХАНИЗМ ЗВУКОВОГО ИСКЛЮЧЕНИЯ\nПерераспределение ресурсов восприятия в пользу зрения за счёт слуха — задокументированы случаи, когда участники не слышали собственные выстрелы или крики рядом.\n\nИСКАЖЕНИЕ ВОСПРИЯТИЯ ВРЕМЕНИ\nСубъективное замедление или ускорение времени — собственная оценка длительности события не является надёжным ориентиром без внешней проверки.\n\nЭФФЕКТЫ НЕ ОДИНАКОВЫ У ВСЕХ\nИнтенсивность варьируется между людьми и ситуациями, зависит от подготовки и от внезапности угрозы — не универсальная константа.\n\nТРЕНИРОВОЧНОЕ ПРОТИВОДЕЙСТВИЕ\nСознательное активное сканирование периферии даже при сфокусированном взаимодействии — применяется в подготовке силовых структур.\n\nСВЯЗЬ С МАТЕРИАЛОМ О НЕСКОЛЬКИХ ПРОТИВНИКАХ\nТоннельное зрение — физиологическое обоснование важности заранее занятой позиции, а не расчёта на боковое зрение в момент стресса.\n\nТИПИЧНЫЕ ОШИБКИ\nРасчёт на автоматическое периферийное зрение без тренировки сканирования; интерпретация неуслышанной команды как невнимательности; полное доверие субъективной оценке времени; ожидание одинаковой интенсивности эффектов у всех.\n\nПРОВЕРЬ СЕБЯ\n1. Что происходит с обработкой периферийного зрения при остром стрессе?\n2. Что такое звуковое исключение?\n3. Как искажается восприятие времени при стрессе?\n4. Одинакова ли интенсивность тоннельного зрения у всех?\n5. Какой приём противодействует тоннельному зрению?'],
['Ментальная репетиция и визуализация','ПРИЗНАННЫЙ ИНСТРУМЕНТ СПОРТИВНОЙ ПСИХОЛОГИИ\nМысленное детальное проигрывание действия десятилетиями применяется в подготовке олимпийских спортсменов, признано измеримо влияющим на результат методом.\n\nФИЗИОЛОГИЧЕСКАЯ ОСНОВА\nФункциональная визуализация мозга показывает активацию тех же нейронных структур при представлении действия, что и при реальном исполнении, с меньшей интенсивностью — задокументированный факт, а не мотивационное преувеличение.\n\nСТРУКТУРА ЭФФЕКТИВНОЙ РЕПЕТИЦИИ\nПредставление от первого лица с сенсорными деталями (зрение, ощущения, звуки) даёт сильнее эффект, чем абстрактное представление.\n\nПРИМЕНЕНИЕ К СЦЕНАРИЯМ КОНФЛИКТА\nРепетиция прежде всего сценариев принятия решения — визуализированное решение об отходе, действия при невозможности отступления, сохранение позиции против группы.\n\nРЕПЕТИЦИЯ НЕУДАЧНОГО ИСХОДА\nМысленная репетиция реакции на осечку, а не только идеального исполнения — снижает риск дезорганизации при реальной, неидеальной ситуации.\n\nРЕГУЛЯРНОСТЬ КАК УСЛОВИЕ ЭФФЕКТИВНОСТИ\nРазовая визуализация даёт минимальный эффект — метод работает как накопительная практика.\n\nОТРАБОТКА ПОЛНОСТЬЮ БЕЗ ПАРТНЁРА\nЕдинственный элемент программы, для которого партнёр по своей природе не требуется вовсе.\n\nТИПИЧНЫЕ ОШИБКИ\nАбстрактная визуализация без сенсорных деталей; репетиция только идеального исхода; ожидание эффекта от разовой практики; недооценка метода как несерьёзного.\n\nПРОВЕРЬ СЕБЯ\n1. Что показывают исследования визуализации мозга о мысленном представлении действия?\n2. Какие детали включает эффективная ментальная репетиция?\n3. Зачем репетировать сценарий неудачи?\n4. Почему разовая визуализация даёт минимальный эффект?\n5. Почему этот метод не требует партнёра по своей природе?'],
['Управление уровнем возбуждения','ЗАКОН ЙЕРКСА-ДОДСОНА\nСформулированная в 1908 году и многократно подтверждённая закономерность: зависимость эффективности от возбуждения имеет форму перевёрнутой U — и низкое, и высокое возбуждение снижают результат, есть оптимальный средний уровень.\n\nПОЧЕМУ НИЗКОЕ ВОЗБУЖДЕНИЕ ТОЖЕ ВРЕДИТ\nНедостаточное возбуждение снижает скорость реакции и готовность к действию так же, как избыточное.\n\nПОЧЕМУ ЧРЕЗМЕРНОЕ ВОЗБУЖДЕНИЕ РАЗРУШАЕТ ИСПОЛНЕНИЕ\nЗапускает потерю мелкой моторики, тоннельное зрение, звуковое исключение, вплоть до замирания — управление означает удержание в продуктивном диапазоне, а не полное устранение реакции.\n\nЗАВИСИМОСТЬ ОТ СЛОЖНОСТИ ЗАДАЧИ\nПростые крупномоторные действия переносят более высокое возбуждение без потери эффективности, чем сложные — согласуется с выбором техники курса.\n\nДЫХАНИЕ КАК ИНСТРУМЕНТ РЕГУЛЯЦИИ\nКонтролируемое дыхание с удлинённым выдохом снижает физиологические показатели возбуждения — тактическое дыхание в подготовке военных и спасателей.\n\nПРЕДВАРИТЕЛЬНАЯ АКТИВАЦИЯ ПРИ НЕДОСТАТОЧНОМ ВОЗБУЖДЕНИИ\nПри слишком низком уровне применяются техники повышения активации — более частое дыхание, физическая активность, переключение внимания.\n\nСВЯЗЬ С МЕНТАЛЬНОЙ РЕПЕТИЦИЕЙ\nРегулярная репетиция снижает элемент внезапности, значительно усиливающий дезорганизующую реакцию по сравнению с ожидаемой угрозой.\n\nИНДИВИДУАЛЬНАЯ КАЛИБРОВКА\nОптимальный уровень индивидуален — постепенная тренировка под нарастающим давлением помогает найти его, а не общие числовые показатели.\n\nТИПИЧНЫЕ ОШИБКИ\nСтремление к полному спокойствию как идеалу; игнорирование зависимости оптимума от сложности задачи; отсутствие практики дыхательной саморегуляции заранее; применение общих показателей без индивидуальной калибровки.\n\nПРОВЕРЬ СЕБЯ\n1. Какую форму имеет зависимость эффективности от возбуждения?\n2. Почему низкое возбуждение вредит результату?\n3. Как сложность задачи влияет на оптимальный уровень возбуждения?\n4. Какой инструмент саморегуляции связывает эту тему с первым модулем?\n5. Как ментальная репетиция помогает управлять возбуждением?'],
['Удар голенью (лоу-кик, мидл-кик, хай-кик)','ПРИНЦИП: УДАР ГОЛЕНЬЮ, А НЕ СТОПОЙ\nКлючевое отличие тайского удара ногой: контакт происходит нижней третью голени, а не подъёмом стопы — голень при должной подготовке выдерживает больший объём нагрузки и передаёт больше массы в цель.\n\nМЕХАНИКА УДАРА: ВРАЩЕНИЕ ВСЕГО ТЕЛА\nУдар начинается с разворота опорной стопы на носке, что позволяет бёдрам и корпусу довернуться следом, разгоняя ногу по широкой дуге, а не выталкивая её одной силой бедра.\n\nТРИ УРОВНЯ УДАРА\nЛоу-кик в бедро вызывает накопительное повреждение при повторах. Мидл-кик в корпус может остановить дыхание или быть заблокирован локтем. Хай-кик в голову требует большей гибкости и скорости, более рискован при промахе.\n\nПРОНОС НОГИ ЧЕРЕЗ ЦЕЛЬ\nНога проносится через цель, продолжая траекторию за точку контакта, увеличивая время воздействия силы, а не отдёргивается сразу.\n\nПОДГОТОВКА ОПОРНОЙ НОГИ\nНедостаточный разворот опорной стопы ограничивает амплитуду и силу удара, нарушение баланса делает уязвимым для контратаки.\n\nЗАЩИТА: БЛОК ГОЛЕНЬЮ\nПодъём собственной голени навстречу атакующей ноге причиняет боль атакующему при столкновении — требует такой же постепенной подготовки, как и сам удар.\n\nВОЗВРАТ В СТОЙКУ ПОСЛЕ УДАРА\nНога быстро возвращается в стойку, задержка в воздухе создаёт уязвимость для захвата ноги противником.\n\nГИБКОСТЬ ДЛЯ ХАЙ-КИКА\nТребует систематической долгосрочной работы над гибкостью тазобедренного сустава, а не единичных попыток растянуться.\n\nТИПИЧНЫЕ ОШИБКИ\nУдар подъёмом стопы вместо голени; удар без разворота опорной стопы; резкое отдёргивание вместо проноса; задержка ноги в воздухе после удара.\n\nПРОВЕРЬ СЕБЯ\n1. Какой частью ноги наносится тайский удар?\n2. С чего начинается механика удара голенью?\n3. Чем отличаются лоу-кик, мидл-кик и хай-кик?\n4. Что означает пронос ноги через цель?\n5. Почему хай-кик требует отдельной работы над гибкостью?'],
['Удары коленом','КОРОТКАЯ ДИСТАНЦИЯ КАК ОБЛАСТЬ ПРИМЕНЕНИЯ\nЭффективен на дистанции слишком близкой для голени или руки — оружие ближнего боя, часто применяемое из клинча.\n\nПРЯМОЕ КОЛЕНО\nНаносится вперёд с движением бедра вверх и подтягиванием опорной ноги на носок. Руки контролируют противника или защищают голову.\n\nБОКОВОЕ КОЛЕНО\nПо дугообразной траектории сбоку, аналогично хуку — применяется, когда прямая линия перекрыта.\n\nРОЛЬ БЁДЕР И КОРПУСА\nИзолированное движение ноги без ротации бёдер даёт значительно более слабый удар — принцип кинетической цепи универсален для всех ударов.\n\nУДАР КОЛЕНОМ В ГОЛОВУ\nНаиболее рискованный и эффективный вариант, требует контроля головы противника рукой — неразрывно связан с темой клинча.\n\nЗАЩИТА ОТ УДАРА КОЛЕНОМ\nНе позволить установить контроль над головой или шеей, либо развернуть бедро для приёма удара мышечной частью.\n\nПОДГОТОВКА КОЛЕННОГО СУСТАВА\nНе является ударной поверхностью, требующей закалки — травмоопасность связана с нагрузкой на сустав при неверной технике.\n\nСАМОСТОЯТЕЛЬНАЯ ОТРАБОТКА\nПрямое и боковое колено по мешку полностью осваивается в одиночку — партнёр нужен для варианта в голову.\n\nТИПИЧНЫЕ ОШИБКИ\nУдар без включения бёдер; пассивные руки во время удара; попытка удара в голову без освоения клинча; недооценка важности техники.\n\nПРОВЕРЬ СЕБЯ\n1. На какой дистанции колено эффективнее голени?\n2. Чем прямое колено отличается от бокового?\n3. Почему изолированное движение ноги даёт слабый удар?\n4. Почему удар в голову связан с клинчем?\n5. Чем отличается подготовка колена от подготовки голени?'],
['Удары локтем','ЛОКОТЬ КАК ОРУЖИЕ БЛИЖАЙШЕЙ ДИСТАНЦИИ\nЭффективен на дистанции короче, чем у колена. Твёрдая узкая поверхность способна нанести рассечение даже при небольшой силе.\n\nГОРИЗОНТАЛЬНЫЙ ЛОКОТЬ\nПо дугообразной траектории за счёт ротации плеча и корпуса, рука согнута на протяжении всего движения.\n\nВОСХОДЯЩИЙ ЛОКОТЬ\nПо вертикальной траектории снизу вверх в подбородок, аналогично апперкоту, с тем же включением ног.\n\nРУБЯЩИЙ ЛОКОТЬ\nСверху вниз с использованием веса корпуса, наклоняющегося вперёд, а не только силы руки.\n\nОБРАТНЫЙ (РАЗВОРОТНЫЙ) ЛОКОТЬ\nС разворотом корпуса на сто восемьдесят градусов — атакует противника вне обычного поля атаки или неожиданно с другой стороны.\n\nПРИНЦИП КИНЕТИЧЕСКОЙ ЦЕПИ\nСила формируется передачей усилия от стоп через бёдра и корпус — локоть одной рукой даёт результат немногим сильнее толчка.\n\nРИСК ДЛЯ НАНОСЯЩЕГО УДАР\nПри неожиданном сближении или уклонении противника локоть может столкнуться с твёрдой частью тела под неудачным углом и травмировать самого бьющего.\n\nСАМОСТОЯТЕЛЬНАЯ ОТРАБОТКА\nВсе варианты осваиваются на мягкой подушке с постепенным увеличением интенсивности.\n\nТИПИЧНЫЕ ОШИБКИ\nУдар без ротации корпуса; работа по слишком жёсткому снаряду; попытка сразу освоить разворотный локоть; недооценка риска травмы собственного локтя.\n\nПРОВЕРЬ СЕБЯ\n1. Почему удар локтем особенно значим в спортивном тайском боксе?\n2. Чем горизонтальный локоть отличается от восходящего?\n3. Что общего у рубящего локтя с работой всего корпуса?\n4. Для чего применяется разворотный локоть?\n5. В чём риск для самого наносящего удар локтем?'],
['Клинч и работа в клинче','ТРЕБУЕТ ПАРТНЁРА\nКлинч — непрерывная борьба за контроль головы и рук при плотном контакте, где каждое действие — реакция на меняющееся сопротивление партнёра, не воспроизводимая без него.\n\nЗАХВАТ ГОЛОВЫ КАК ЦЕНТРАЛЬНЫЙ ЭЛЕМЕНТ\nОбе руки обхватывают шею сзади, локти прижаты к плечам противника — из этой позиции возможны удары коленом и броски.\n\nБОРЬБА ЗА ПОЗИЦИЮ ВНУТРИ КЛИНЧА\nРуки внутри дают больше контроля, снаружи вынуждают обороняться — непрерывный динамический процесс на протяжении всего клинча.\n\nСВЯЗЬ С ПРИНЦИПАМИ СИСТЕМЫ КАДОЧНИКОВА\nРывки эффективнее не за счёт силы, а за счёт нарушения уже смещённого равновесия — тот же принцип работы с чужой силой.\n\nЗАЩИТА И ВЫХОД ИЗ КЛИНЧА\nТребует работы рук (подныривание, внутреннее положение) и ног (угол через шаг в сторону, а не прямое отступление).\n\nПОСТЕПЕННОСТЬ ОСВОЕНИЯ\nОт пассивного партнёра к лёгкому сопротивлению и лишь затем к свободной борьбе — пропуск этапов повышает риск травмы шеи.\n\nБЕЗОПАСНОСТЬ РАБОТЫ В КЛИНЧЕ\nТребует того же сигнала остановки и контроля силы — рывки к шее в полную силу без осторожного знакомства недопустимы даже на продвинутом этапе.\n\nТИПИЧНЫЕ ОШИБКИ\nПопытка имитировать клинч без партнёра; пропуск ступеней постепенности; грубая сила вместо использования смещения равновесия; недостаточное внимание к безопасности шеи.\n\nПРОВЕРЬ СЕБЯ\n1. Почему клинч невозможно отработать без партнёра?\n2. Как устроена стандартная позиция захвата?\n3. Что такое борьба за позицию рук в клинче?\n4. Как принцип Кадочникова применяется в клинче?\n5. Из каких ступеней состоит постепенная отработка клинча?'],
['Принцип короткой дистанции','ФИЛОСОФИЯ ДУАНЬДА В КОНТЕКСТЕ ПРОГРАММЫ\nДуаньда (короткий удар) — подход, где эффективность достигается не длинной разогнанной траекторией, как в кроссе или ударе голенью, а минимальной амплитудой с полной мгновенной передачей усилия тела. Дополняет ударную базу бокса и муай-тай на дистанции, слишком короткой для размаха.\n\nПОЧЕМУ КОРОТКАЯ ДИСТАНЦИЯ ТРЕБУЕТ ИНОЙ МЕХАНИКИ\nНа дальней дистанции сила накапливается длинной траекторией разгона. На короткой такой траектории физически нет — дуаньда переносит источник силы на резкое движение корпуса и бёдер.\n\nСИЛА НА МИНИМАЛЬНОЙ АМПЛИТУДЕ\nМинимальный видимый замах труднее предугадать и позволяет бить там, где нет пространства для полноценного размаха.\n\nПОНЯТИЕ "ЦУНЬ ЦЗИНЬ"\nВ традиции южнокитайских школ короткого удара, включая известную по демонстрациям вин-чун, существует концепция предельно короткого взрывного удара — общий принцип роднит эти традиции.\n\nОТЛИЧИЕ ОТ ПОДХОДА БОКСА И МУАЙ-ТАЙ К ДИСТАНЦИИ\nБокс и муай-тай избегают опасной короткой зоны через контроль дистанции. Дуаньда рассматривает эту зону как рабочую область со своим арсеналом — логичное дополнение, а не противоречие.\n\nЦЕЛОСТНОСТЬ ТЕЛА КАК ТРЕБОВАНИЕ\nПоскольку сила не накапливается разгоном, всё тело должно действовать как единая система — любое рассогласование немедленно снижает эффективность, компенсировать нечем.\n\nСВЯЗЬ С ОБЩЕЙ ПРОГРАММОЙ\nДуаньда занимает промежуточное положение между дальней ударной работой и клинчем или борьбой, заполняя дистанционный промежуток.\n\nТИПИЧНЫЕ ОШИБКИ\nПопытка применить технику с длинным разгоном на короткой дистанции; недооценка требования к телесной координации; восприятие короткой дистанции только как опасной зоны для избегания.\n\nПРОВЕРЬ СЕБЯ\n1. Чем источник силы в дуаньда отличается от источника силы в ударах дальней дистанции?\n2. Почему удар с минимальной амплитудой труднее предугадать?\n3. Как дуаньда дополняет тактику бокса и муай-тай?\n4. Почему короткая дистанция требует более полной координации?\n5. Какое место дуаньда занимает в структуре курса по переходу между дальностями?'],
['Удары ладонью и кулаком с близкой дистанции','ПАЛЬМОВЫЙ УДАР КАК ХАРАКТЕРНОЕ ОРУЖИЕ\nУдар основанием ладони применяется там, где не хватает дистанции для разгона кулака — более широкая устойчивая поверхность снижает риск травмы руки.\n\nВЕРТИКАЛЬНЫЙ КУЛАК\nВ отличие от горизонтального положения в боксе, вертикальное положение органичнее для короткой прямой траектории и снижает нагрузку на лучезапястный сустав.\n\nУДАР ЛОКТЕВОЙ СТОРОНОЙ КУЛАКА\nКороткая рубящая траектория для дистанции, где даже минимальный прямой удар не помещается по пространству.\n\nРАБОТА БЕЗ ПОДГОТОВИТЕЛЬНОГО ЗАМАХА\nУдар наносится прямо из текущего положения — замах на такой дистанции либо невозможен, либо мгновенно раскрывает атаку. Сила формируется резким импульсом от бёдер и корпуса.\n\nПРИМЕНЕНИЕ ПОСЛЕ УКЛОНА ИЛИ БЛОКА\nНаиболее востребованы сразу после защитного действия из модуля бокса, когда дистанция уже сократилась, а стандартная техника ещё не применима.\n\nСЕРИЙНОСТЬ КОРОТКИХ УДАРОВ\nСерия быстрых ударов по разным целям компенсирует ограниченную силу каждого отдельного удара их частотой.\n\nЦЕЛИ ДЛЯ УДАРОВ КОРОТКОЙ ДИСТАНЦИИ\nСмещены к более уязвимым зонам, требующим меньшей силы: подбородок, горло с осторожностью, область под рёбрами.\n\nСАМОСТОЯТЕЛЬНАЯ ОТРАБОТКА\nПолностью осваивается на мешке с особым вниманием к отсутствию неосознанного замаха, проверяемому перед зеркалом.\n\nТИПИЧНЫЕ ОШИБКИ\nНеосознанное отведение руки назад; горизонтальное положение кулака вместо вертикального; работа только одиночными ударами; недостаточная осторожность с ударами в горло.\n\nПРОВЕРЬ СЕБЯ\n1. Почему основание ладони подходит для предельно короткой дистанции?\n2. Чем вертикальное положение кулака отличается от горизонтального?\n3. Почему удар наносится без предварительного замаха?\n4. В какой ситуации из модуля бокса востребованы эти удары?\n5. Как компенсируется ограниченная сила единичного удара?'],
['Работа корпусом и бёдрами (фацзинь)','ФАЦЗИНЬ КАК ОБЩИЙ ПРИНЦИП\nТермин означает резкое взрывное высвобождение силы, используется в внутренних и внешних китайских стилях, включая дуаньда — в отличие от постепенного наращивания силы в длинной технике.\n\nОТЛИЧИЕ ОТ РОТАЦИИ КОРПУСА В БОКСЕ\nКинетическая цепь здесь доводится до предела: звенья срабатывают почти одновременно единым импульсом, а не последовательной волной, как в длинной технике.\n\nРОЛЬ ТАЗОБЕДРЕННЫХ СУСТАВОВ И ПОЯСНИЦЫ\nРезкий разворот бёдер, инициируемый едва заметным проворотом стопы, — источник импульса. Недостаточная подвижность ограничивает силу удара.\n\nРАССЛАБЛЕНИЕ ДО МОМЕНТА УДАРА\nТело остаётся расслабленным до контакта, полное напряжение — на исчезающе короткий момент. Заранее существующее напряжение замедляет движение и снижает силу.\n\nСВЯЗЬ С ДЫХАНИЕМ ИЗ ПЕРВОГО МОДУЛЯ\nРезкий выдох синхронизирует напряжение кора именно с моментом контакта — дыхание и усилие здесь неразделимые аспекты одного действия.\n\nПРАКТИЧЕСКАЯ ПРОВЕРКА\nРука на бедре или животе перед зеркалом при ударе позволяет почувствовать, есть ли резкое сокращение мышц корпуса, синхронизированное с ударом.\n\nСАМОСТОЯТЕЛЬНАЯ ОТРАБОТКА\nТребует значительно большего числа повторений, чем ротация в боксе, поскольку переучивает интуитивную привычку напрягаться заранее.\n\nТИПИЧНЫЕ ОШИБКИ\nПостоянное напряжение вместо точечного взрывного; медленное заметное прокручивание бёдер вместо резкого импульса; недостаточная работа над подвижностью; рассинхронизация дыхания и усилия.\n\nПРОВЕРЬ СЕБЯ\n1. Что означает фацзинь и где используется?\n2. Чем передача усилия в коротком ударе отличается от кинетической цепи бокса по времени?\n3. Почему тело должно быть расслаблено до момента удара?\n4. Как дыхание связано с фацзинь?\n5. Каким способом проверить включение корпуса в удар?'],
['Формальные комплексы (таолу) короткого удара','ТАОЛУ КАК ФОРМА БЕЗ ПАРТНЁРА\nЗаранее заученная последовательность движений, выполняемая в одиночку — основной инструмент сохранения техники и полноценная форма самостоятельной тренировки.\n\nФУНКЦИИ ТАОЛУ ПОМИМО ЗАУЧИВАНИЯ\nРазвивает непрерывность переходов, устойчивость при смене направления, дыхательный ритм с фацзинь, общую выносливость при повторении.\n\nСТРУКТУРА ОСВОЕНИЯ КОМПЛЕКСА\nОт отдельных движений к коротким связкам и лишь затем к целому комплексу — заучивание целиком с первого раза замедляет освоение.\n\nСКОРОСТЬ ВЫПОЛНЕНИЯ КАК ПЕРЕМЕННАЯ\nМедленное исполнение развивает точность и баланс, быстрое — взрывную силу и синхронизацию с дыханием. Оба режима дополняют друг друга.\n\nПРИМЕНИМОСТЬ ЭЛЕМЕНТОВ К РЕАЛЬНОЙ СИТУАЦИИ\nНе каждое движение комплекса напрямую прикладное — часть стилизована. Задача — извлекать принципы, а не копировать движения буквально.\n\nСВЯЗЬ С ОСТАЛЬНОЙ ПРОГРАММОЙ\nВходит в общую категорию отработки формы без сопротивления вместе с теневым боем и повторением падений.\n\nЗАПИСЬ СОБСТВЕННОГО ИСПОЛНЕНИЯ\nВидеозапись с сравнением с эталоном — основной доступный способ самокоррекции без партнёра или инструктора.\n\nТИПИЧНЫЕ ОШИБКИ\nЗаучивание целиком без разбора на элементы; работа на одной скорости; буквальное копирование стилизованных движений; отсутствие видеозаписи для самокоррекции.\n\nПРОВЕРЬ СЕБЯ\n1. Какую роль играет таолу помимо сохранения техники?\n2. В каком порядке строится разучивание комплекса?\n3. Зачем отрабатывать на разных скоростях?\n4. Почему не каждое движение — буквальная боевая техника?\n5. Какой инструмент важен для самоконтроля без партнёра?'],
['Принцип рычага и работы с чужой силой','ЦЕНТРАЛЬНАЯ ИДЕЯ СИСТЕМЫ КАДОЧНИКОВА\nРазработанная Алексеем Кадочниковым на основе инженерного образования, система описывает технику языком прикладной механики — рычаги, векторы, моменты вращения, а не набором изолированных приёмов.\n\nРЫЧАГ КАК ФИЗИЧЕСКИЙ ПРИНЦИП\nВоздействие на сустав через точку, удалённую от оси вращения, требует значительно меньшего усилия, чем прямое преодоление сопротивления силой против силы в точке контакта.\n\nПОЧЕМУ "НЕ ПРОТИВОСТОЯТЬ, А НАПРАВЛЯТЬ"\nНе пассивная покорность, а точный расчёт: эффективнее добавить небольшое усилие к уже существующему движению противника, чем останавливать его полностью встречным сопротивлением.\n\nВЕКТОР СИЛЫ И ЕГО РАЗЛОЖЕНИЕ\nСила толчка может быть частично перенаправлена небольшим боковым усилием, использующим часть исходного вектора для вращения, а не для прямого противодействия.\n\nОПОРА КАК ОБЯЗАТЕЛЬНОЕ УСЛОВИЕ\nРычаг работает только относительно неподвижной опоры — эффективное воздействие на сустав требует одновременного контроля второй точки как опоры.\n\nМОМЕНТ СИЛЫ И ДЛИНА ПЛЕЧА РЫЧАГА\nЧем дальше точка приложения силы от оси вращения сустава, тем меньше требуется усилие для того же момента вращения.\n\nОТЛИЧИЕ ОТ ГРУБОЙ СИЛОВОЙ БОРЬБЫ\nПравильно применённый рычаг делает исход менее зависимым от абсолютной мышечной силы каждой стороны.\n\nТЕОРИЯ КАК ПРЕДВАРИТЕЛЬНОЕ УСЛОВИЕ\nВ отличие от ударной техники, принцип рычага не может быть прочувствован без реального сопротивления партнёра.\n\nТИПИЧНЫЕ ОШИБКИ\nПонимание принципа как полной пассивности; рычаг без контроля опорной точки; воздействие близко к оси вращения; расчёт на теорию вместо практики с партнёром.\n\nПРОВЕРЬ СЕБЯ\n1. Чем система Кадочникова отличается по способу описания техники?\n2. Что означает "не противостоять, а направлять" технически?\n3. Почему рычагу нужна опора?\n4. Как длина плеча рычага связана с требуемым усилием?\n5. Почему теория не заменяет практику с партнёром?'],
['Уходы с линии атаки','ПРИНЦИП: НЕ ОСТАНАВЛИВАТЬ, А ПЕРЕСТАТЬ БЫТЬ ЦЕЛЬЮ\nВ отличие от блокирования, уход смещает тело так, чтобы траектория атаки прошла мимо, без силового противодействия импульсу.\n\nСМЕЩЕНИЕ ПОД УГЛОМ\nСмещение выполняется по диагонали, а не прямым отступлением назад — прямое отступление лишь отсрочивает контакт, уход под углом полностью выводит из траектории.\n\nСВЯЗЬ С ПЕРЕНОСОМ ВЕСА\nУход начинается с переноса центра тяжести, а не с движения ногой — эффективность зависит от усвоения этого базового принципа первого модуля.\n\nИСПОЛЬЗОВАНИЕ УХОДА ДЛЯ ВЫГОДНОЙ ПОЗИЦИИ\nУход создаёт позицию сбоку или сзади противника, из которой возможно немедленное продолжение действия, поскольку противник временно менее устойчив.\n\nРАБОТА ПРОТИВ РАЗНЫХ ТИПОВ АТАК\nПротив прямого удара достаточно небольшого смещения; против атаки с оружием требуется большая амплитуда и контроль вооружённой конечности.\n\nЧУВСТВО ДИСТАНЦИИ И ВРЕМЕНИ\nУход, начатый слишком рано, позволяет противнику скорректировать движение; начатый слишком поздно — не успевает вывести из-под атаки.\n\nЧАСТИЧНАЯ САМОСТОЯТЕЛЬНАЯ ОТРАБОТКА\nБазовая механика частично отрабатывается против воображаемой атаки, но полноценная адаптация к скорости требует партнёра.\n\nТИПИЧНЫЕ ОШИБКИ\nПрямое отступление вместо смещения под углом; уход без предварительного переноса веса; отсутствие использования созданной позиции; недостаточная постепенность перехода к быстрым атакам.\n\nПРОВЕРЬ СЕБЯ\n1. Чем уход отличается от блокирования?\n2. Почему смещение под углом эффективнее отступления назад?\n3. Как уход связан с переносом веса из первого модуля?\n4. Почему уход редко самостоятельное действие?\n5. Что происходит при слишком раннем или позднем уходе?'],
['Работа с равновесием противника','ТРЕБУЕТ ПАРТНЁРА\nРабота с равновесием описывает взаимодействие с реальным смещением центра тяжести другого человека — не воспроизводима без партнёра, в отличие от предыдущей темы.\n\nЦЕНТР ТЯЖЕСТИ ПРОТИВНИКА КАК ЦЕЛЬ\nВывод из равновесия рассматривается как самостоятельная задача, часто более значимая, чем сила удара, поскольку потерявший равновесие временно теряет координацию.\n\nОПРЕДЕЛЕНИЕ НАПРАВЛЕНИЯ УЖЕ СУЩЕСТВУЮЩЕГО СМЕЩЕНИЯ\nОпределение, куда уже смещён вес противника, чтобы добавить усилие, продолжающее это смещение, а не создающее новое — прямое применение принципа рычага.\n\nМОМЕНТ ПРИЛОЖЕНИЯ УСИЛИЯ КАК КЛЮЧЕВАЯ ПЕРЕМЕННАЯ\nТочный момент приложения силы относительно фазы движения противника важнее величины усилия.\n\nМАЛАЯ АМПЛИТУДА КАК ПРИЗНАК ПРАВИЛЬНОГО ИСПОЛНЕНИЯ\nВерно исполненное воздействие требует заметно меньше усилия, чем ожидается — потребность в большой силе указывает на неверный момент или направление.\n\nПОСТЕПЕННОСТЬ ОСВОЕНИЯ С ПАРТНЁРОМ\nОт партнёра, сознательно смещающего вес медленно, к лёгкому сопротивлению и лишь затем к естественному темпу.\n\nСВЯЗЬ С ПОСЛЕДУЮЩИМИ ТЕМАМИ\nНавык напрямую переносится на клинч муай-тай и на броски самбо в следующем модуле.\n\nТИПИЧНЫЕ ОШИБКИ\nВывод из равновесия мышечной силой вместо точного момента; воздействие при устойчивом весе партнёра; пропуск постепенных ступеней; недооценка невозможности соло-отработки.\n\nПРОВЕРЬ СЕБЯ\n1. Почему эта тема совсем не поддаётся соло-отработке?\n2. Почему вывод из равновесия часто значимее силы удара?\n3. Что важнее — величина силы или момент приложения?\n4. О чём говорит необходимость большой силы для вывода из равновесия?\n5. С какими темами связан этот навык?'],
['Базовые контроли и загибы руки','ТРЕБУЕТ ПАРТНЁРА\nПрямое применение принципа рычага к запястью и локтю — болевое воздействие требует реального сопротивления партнёра для калибровки границы контроля.\n\nЗАГИБ РУКИ ЗА СПИНУ КАК БАЗОВЫЙ КОНТРОЛЬ\nСоздаёт два эффекта: болевое воздействие на запястье и плечо и вывод из равновесия вперёд-вниз за счёт неестественного положения плеча.\n\nРЫЧАГ НА ЛОКОТЬ ЧЕРЕЗ ЗАПЯСТЬЕ\nКонтроль за запястье (длинное плечо рычага) с фиксацией плеча как опоры создаёт значительное воздействие при небольшом усилии.\n\nПОСТОЯННЫЙ КОНТРОЛЬ РЕАКЦИИ ПАРТНЁРА\nБолевой приём травмирует почти мгновенно после предела подвижности без предупреждения — внимание к сигналам партнёра часть самой техники, а не дополнительная мера.\n\nПОСТЕПЕННОЕ УВЕЛИЧЕНИЕ АМПЛИТУДЫ\nОт безопасной амплитуды к постепенно приближающейся к пределу, с остановкой заметно раньше границы на протяжении всего освоения.\n\nПРИКЛАДНОЕ, А НЕ СПОРТИВНОЕ ЗАВЕРШЕНИЕ\nЦель — контролируемое достижение достаточного воздействия без обязательного доведения до предельной точки, которая на реальном партнёре означает травму.\n\nСВЯЗЬ С МАТЕРИАЛОМ О НЕСКОЛЬКИХ ПРОТИВНИКАХ\nПродолжительное удержание контроля крайне противопоказано при наличии рядом других противников.\n\nТИПИЧНЫЕ ОШИБКИ\nВоздействие без контроля реакции партнёра; форсирование амплитуды быстрее освоения; спортивная модель доведения до сдачи в учебной практике; удержание контроля при других противниках рядом.\n\nПРОВЕРЬ СЕБЯ\n1. Какие два эффекта создаёт загиб руки за спину?\n2. Как принцип длинного плеча рычага применяется к запястью и локтю?\n3. Почему контроль реакции партнёра — часть самой техники?\n4. Чем прикладное завершение отличается от спортивной модели?\n5. Почему удержание контроля противопоказано при нескольких противниках?'],
['Захваты и борьба за захват','ЗАХВАТ КАК ПРЕДПОСЫЛКА ЛЮБОГО БРОСКА\nПрежде чем становится возможным бросок, необходимо установить захват — контакт с телом или одеждой противника. В самбо захваты устанавливаются как за тело, так и за одежду, что открывает более широкий арсенал, чем в системах без работы с одеждой.\n\nБАЗОВЫЕ ТОЧКИ ЗАХВАТА\nОтворот куртки, рукав, пояс, предплечье или плечо. Захват за отворот у горла облегчает вывод из равновесия вперёд, захват за пояс сбоку облегчает броски через бедро.\n\nБОРЬБА ЗА ЗАХВАТ КАК ОТДЕЛЬНАЯ ФАЗА\nПериод взаимной борьбы за выгодный захват требует постоянного движения рук и мгновенного использования открывшихся возможностей, а не статичного удержания позиции.\n\nСИММЕТРИЧНЫЙ И НЕСИММЕТРИЧНЫЙ ЗАХВАТ\nСимметричный захват балансирован, несимметричный (контроль двумя руками против одной) даёт значительное тактическое преимущество и часто предпосылку для броска.\n\nЗАХВАТ КАК ИНСТРУМЕНТ КОНТРОЛЯ РАВНОВЕСИЯ\nУстановленный захват уже позволяет ощущать распределение веса противника задолго до попытки броска — прямая связь с модулем Кадочникова.\n\nОСВОБОЖДЕНИЕ ОТ ЗАХВАТА\nРазрыв невыгодного захвата резким движением в сторону, где хват соперника структурно слабее (сторона большого пальца).\n\nДИСТАНЦИЯ И СТОЙКА\nБорцовская стойка ниже и шире общей стойки, колени согнуты сильнее, корпус наклонён вперёд для затруднения захвата.\n\nТИПИЧНЫЕ ОШИБКИ\nСтатичное удержание захвата без улучшения позиции; попытка броска без структурного преимущества; игнорирование информации о равновесии на стадии захвата; недостаточно устойчивая стойка.\n\nПРОВЕРЬ СЕБЯ\n1. За какие точки устанавливается захват в самбо?\n2. Чем симметричный захват отличается от несимметричного?\n3. Как захват связан с материалом о равновесии противника?\n4. В какую сторону эффективнее разрывать невыгодный захват?\n5. Чем борцовская стойка отличается от общей стойки первого модуля?'],
['Броски через бедро и подсечки','БРОСОК ЧЕРЕЗ БЕДРО КАК КЛАССИЧЕСКАЯ ТЕХНИКА\nИсполняющий разворачивается спиной к противнику, подводит бедро под его таз, наклоном корпуса и вращением переворачивает через себя. Успех определяется подведением бедра под центр тяжести, а не силой рук.\n\nСВЯЗЬ С РАБОТОЙ НА РАВНОВЕСИЕ\nБросок эффективнее, если вес противника уже смещён вперёд, а не устойчиво распределён на обе ноги.\n\nПОДБИВ БЕДРОМ КАК МЕХАНИЧЕСКАЯ ОСНОВА\nПлотный контакт бедра с тазом до подъёма создаёт точку опоры для вращения — недостаточный подшаг резко снижает эффективность независимо от силы рывка.\n\nЗАДНЯЯ ПОДСЕЧКА\nАтака голеностопа опорной ноги точно в момент переноса веса на неё, с одновременным рывком руками в противоположном направлении. Синхронизация с фазой шага важнее самой механики движения.\n\nБОКОВАЯ ПОДСЕЧКА\nАтака вбок при боковом движении противника, использующая уже существующий боковой компонент смещения веса.\n\nСВЯЗЬ С ПРИНЦИПОМ РЫЧАГА\nНога, лишённая опоры под весом, действует как короткое плечо рычага относительно центра тяжести — небольшое усилие создаёт значительный момент вращения.\n\nПОДГОТОВИТЕЛЬНОЕ ДВИЖЕНИЕ И ПРОВОКАЦИЯ ШАГА\nНа продвинутом уровне нужный шаг активно провоцируется, а не ожидается пассивно.\n\nПАДЕНИЕ КАК ЗАВЕРШЕНИЕ\nОба участника должны уверенно владеть укеми прежде отработки в реальном темпе.\n\nТИПИЧНЫЕ ОШИБКИ\nБросок без плотного контакта бедра; подсечка без синхронизации с переносом веса; отработка до освоения укеми; игнорирование возможности провоцировать момент.\n\nПРОВЕРЬ СЕБЯ\n1. Что определяет успешность броска через бедро?\n2. Когда бросок через бедро эффективнее?\n3. Какой момент критичен для задней подсечки?\n4. Как подсечка применяет принцип рычага?\n5. Какой навык обязателен для отработки обоими партнёрами?'],
['Броски с падением (жертвенные)','ЧТО ОТЛИЧАЕТ ЖЕРТВЕННЫЕ БРОСКИ\nИсполняющий сознательно уходит вниз вместе с противником, используя собственный вес для усиления броска, вместо сохранения устойчивого положения стоя.\n\nПОВЫШЕННЫЙ РИСК КАК ХАРАКТЕРИСТИКА ГРУППЫ\nОба участника оказываются на земле одновременно — требует ещё более уверенного укеми у обоих, чем для техник без падения исполняющего.\n\nИСПОЛЬЗОВАНИЕ СОБСТВЕННОГО ВЕСА КАК РЫЧАГА\nПадение собственным телом добавляет массу и импульс к воздействию, позволяя бросить более тяжёлого соперника, чем силой одних рук.\n\nТИПОВОЙ ПРИМЕР МЕХАНИКИ\nИсполняющий резко садится или падает на бок, увлекая противника через захват так, что тот перелетает и приземляется с большей силой, чем сам исполняющий.\n\nСИНХРОНИЗАЦИЯ С МОМЕНТОМ ВЫВОДА ИЗ РАВНОВЕСИЯ\nЭффективность резко возрастает при синхронизации с уже нарушенным равновесием противника, а не как изолированное действие.\n\nОСОБАЯ ВАЖНОСТЬ УКЕМИ ОБОИХ УЧАСТНИКОВ\nОтработка хотя бы с одним партнёром, не владеющим укеми уверенно, создаёт неприемлемый риск для обоих одновременно.\n\nПОСТЕПЕННОСТЬ КАК ОСОБО СТРОГОЕ ТРЕБОВАНИЕ\nГрадация реализма соблюдается строже, чем для менее рискованных техник — переход к реалистичному темпу медленнее и осторожнее.\n\nОГРАНИЧЕННОЕ ПРИМЕНЕНИЕ ПРОТИВ ГРУППЫ\nЖертвенные броски — едва ли не худший выбор при нескольких противниках, поскольку лишают контроля позиции на время падения — допустимы только как крайняя мера.\n\nТИПИЧНЫЕ ОШИБКИ\nОтработка без уверенного укеми у обоих; бросок без синхронизации с равновесием; слишком быстрый переход к реализму; применение при нескольких противниках без крайней необходимости.\n\nПРОВЕРЬ СЕБЯ\n1. Чем жертвенные броски отличаются от броска через бедро по положению исполняющего?\n2. Почему эта группа объективно рискованнее?\n3. Как собственный вес используется как элемент принципа рычага?\n4. Почему постепенность строже для этой группы?\n5. Почему жертвенные броски противопоказаны при нескольких противниках?'],
['Защита от захватов и бросков','ЗАЩИТА КАК РАВНОЗНАЧНАЯ ЧАСТЬ ПРОГРАММЫ\nПартнёры должны регулярно меняться ролями, развивая и атакующий, и защитный навык, а не закрепляя привычку только к одной роли.\n\nПРЕВЕНТИВНАЯ ЗАЩИТА НА СТАДИИ ЗАХВАТА\nНе позволяя сопернику установить выгодный захват изначально, защищающийся снижает саму вероятность броска вместо реактивной защиты постфактум.\n\nКОНТРОЛЬ РАВНОВЕСИЯ КАК ОСНОВА ЗАЩИТЫ\nШирокая устойчивая стойка с низким центром тяжести затрудняет вывод из равновесия — большинство бросков зависят от предварительного его нарушения.\n\nЗАЩИТА ОТ БРОСКА ЧЕРЕЗ БЕДРО: ОТВОД ТАЗА\nСвоевременное отведение таза в момент разворота соперника лишает его плотного контакта бедра, без которого техника резко теряет эффективность.\n\nЗАЩИТА ОТ ПОДСЕЧКИ: КОНТРОЛЬ ФАЗЫ ШАГА\nСознательный контроль шага, избегание предсказуемого переноса веса, быстрое смещение веса обратно при ощущении атаки на опорную ногу.\n\nПАДЕНИЕ КАК ВЫНУЖДЕННАЯ, НО КОНТРОЛИРУЕМАЯ ЗАЩИТА\nКогда предотвратить падение уже невозможно, задача смещается на контролируемое исполнение через укеми — практическая причина, почему укеми осваивается раньше всей бросковой техники.\n\nЗАЩИТА ОТ ЖЕРТВЕННЫХ БРОСКОВ КАК ОСОБЫЙ СЛУЧАЙ\nОтступление назад усугубляет ситуацию — эффективнее сместить вес перпендикулярно направлению броска, оставаясь на ногах сбоку.\n\nПРАКТИКА ЗАЩИТЫ КАК ФОРМАТ ТРЕНИРОВКИ\nЗаранее оговорённый медленный бросок, защита партнёра, остановка и обсуждение — та же градация реализма, применённая к защитной стороне.\n\nТИПИЧНЫЕ ОШИБКИ\nТолько реактивная защита вместо превентивной; недостаточно устойчивая стойка; попытка предотвратить неизбежное падение вместо контролируемого укеми; отступление назад при жертвенном броске.\n\nПРОВЕРЬ СЕБЯ\n1. Почему эффективная защита начинается раньше момента самого броска?\n2. Как контроль равновесия связывает тему с первым модулем?\n3. Какая защита применяется против броска через бедро?\n4. Что происходит с задачей защищающегося, если падение уже неизбежно?\n5. Почему отступление назад плохая реакция на жертвенный бросок?'],
['Базовые позиции контроля','ПЕРЕХОД ОТ БРОСКА К ПАРТЕРУ\nУспешный бросок редко самоцель — он создаёт ситуацию, где то, что происходит в первые секунды после падения, определяет, сохранится ли преимущество. Партер — работа в этой фазе, где действуют иные законы контроля, чем в стойке.\n\nУДЕРЖАНИЕ СВЕРХУ КАК БАЗОВЫЙ ПРИНЦИП\nНаходящийся сверху обладает преимуществом за счёт собственного веса под действием силы тяжести — преимущество нужно активно удерживать, а не просто занять один раз.\n\nПОЗИЦИЯ КОНТРОЛЯ СБОКУ\nКонтролирующий располагается сбоку, прижимая грудью и весом, одна рука контролирует голову или дальнюю руку, другая опирается в пол. Ноги расставлены широко, а не сведены — сведённые легко нарушить рывком снизу.\n\nПОЗИЦИЯ КОНТРОЛЯ ВДОЛЬ ТЕЛА\nБолее доминирующая позиция поперёк корпуса, затрудняющая использование ног снизу — требует хорошего чувства баланса, поскольку контролирующий частично лишён опоры на пол.\n\nПОЗИЦИЯ СО СТОРОНЫ ГОЛОВЫ\nЭффективна для контроля обеих рук противника одновременно и для перехода к болевым приёмам на руку.\n\nПРИНЦИП ДАВЛЕНИЯ ВЕСОМ, А НЕ СИЛОЙ\nЭффективное удержание опирается на распределение веса на неудобные точки тела противника, а не на удержание руками, которое быстро утомляет и менее устойчиво к рывкам.\n\nСВЯЗЬ С РАВНОВЕСИЕМ ИЗ МОДУЛЯ КАДОЧНИКОВА\nЛежащий снизу постоянно пытается сместить вес для побега — контролирующий должен непрерывно отслеживать это и корректировать положение, а не полагаться на статичную позицию.\n\nПЕРЕХОД МЕЖДУ ПОЗИЦИЯМИ\nОпытный борец плавно переходит между позициями в ответ на сопротивление, используя смену как создание новой выгодной ситуации, а не как признак утраты контроля.\n\nТИПИЧНЫЕ ОШИБКИ\nУдержание мышцами рук вместо распределения веса; сведённые ноги при боковом контроле; статичное удержание одной позиции; недостаточное внимание к смещению веса лежащего противника.\n\nПРОВЕРЬ СЕБЯ\n1. Почему первые секунды после броска определяют сохранение преимущества?\n2. За счёт чего верхний обладает структурным преимуществом?\n3. Чем контроль сбоку отличается от контроля вдоль тела?\n4. Почему удержание опирается на вес, а не на силу рук?\n5. Почему борец переходит между позициями вместо удержания одной?'],
['Болевые приёмы на руку','ПРОДОЛЖЕНИЕ ПРИНЦИПА РЫЧАГА В ПАРТЕРЕ\nБолевые на руку используют тот же принцип рычага, но с большими структурными возможностями фиксации опоры весом всего тела, а не одной руки.\n\nРЫЧАГ ЛОКТЯ КАК БАЗОВАЯ ТЕХНИКА\nРука фиксируется выпрямленной, локоть зажимается между бёдрами, давление на запястье создаёт воздействие на сустав. Согнутая рука не позволяет создать чистый рычаг независимо от усилия.\n\nУЗЕЛ ПЛЕЧА\nРаботает на ротационное скручивание плечевого сустава, а не линейное разгибание — требует иного захвата и фиксации.\n\nПОСТЕПЕННОЕ ПРИЛОЖЕНИЕ ДАВЛЕНИЯ\nДавление наращивается медленно, давая время на сигнал остановки — резкое приложение полной силы не оставляет этого времени.\n\nРАЗЛИЧИЕ УЧЕБНОГО И РЕАЛЬНОГО ПРИМЕНЕНИЯ\nВ учебной отработке приём останавливается заметно раньше предела при получении сигнала — прикладное, а не спортивное завершение.\n\nКОНТРОЛЬ КИСТИ КАК АЛЬТЕРНАТИВНАЯ ЦЕЛЬ\nМенее мощная техника, но требующая меньшей структурной фиксации всего тела, применима при неполном контроле позиции.\n\nСВЯЗЬ С МАТЕРИАЛОМ О НЕСКОЛЬКИХ ПРОТИВНИКАХ\nПродолжительное удержание болевого на руку противопоказано при других противниках рядом по той же логике, что и загиб руки Кадочникова.\n\nТИПИЧНЫЕ ОШИБКИ\nРычаг локтя на согнутую руку; резкое приложение давления в учёбе; путаница рычага и узла; удержание при нескольких противниках.\n\nПРОВЕРЬ СЕБЯ\n1. Что определяет эффективность рычага локтя?\n2. Чем узел плеча отличается от рычага локтя?\n3. Почему давление наращивается постепенно?\n4. Для чего применяется контроль кисти?\n5. Почему удержание противопоказано при нескольких противниках?'],
['Болевые приёмы на ногу','ОБЩИЙ ПРИНЦИП, ПЕРЕНЕСЁННЫЙ С РУКИ\nЛогика фиксации опоры, рычага на сустав, постепенности давления переносится с руки на ногу, хотя захваты отличаются из-за большей силы мышц ног.\n\nУЩЕМЛЕНИЕ АХИЛЛОВА СУХОЖИЛИЯ\nГоленостоп фиксируется, предплечье давит на сухожилие над пяткой при контроле бедра как опоры, предотвращающей сгибание ноги.\n\nРЫЧАГ КОЛЕННОГО СУСТАВА\nВоздействие на прямую ногу против естественного сгиба колена — требует особой осторожности, поскольку колено более уязвимо к боковой и ротационной нагрузке, а травма серьёзнее рычага локтя.\n\nБОЛЬШАЯ СИЛА НОГ КАК ОСЛОЖНЯЮЩИЙ ФАКТОР\nНоги значительно сильнее рук — требуется фиксация опоры всем весом тела, попытка удержать только руками неэффективна.\n\nПОВЫШЕННАЯ ОСТОРОЖНОСТЬ ПРИ ОТРАБОТКЕ\nРезкое воздействие способно повредить связки колена быстрее и при меньшей амплитуде превышения предела, чем для локтя или плеча.\n\nПОЗИЦИОННАЯ БЕЗОПАСНОСТЬ ДЛЯ ИСПОЛНЯЮЩЕГО\nКонтролирующий менее защищён от удара свободной ногой противника — требуется осознанное позиционирование относительно неё.\n\nСВЯЗЬ С БЕЗОПАСНОСТЬЮ ПАРНОЙ РАБОТЫ\nПостоянный контроль реакции и немедленная остановка особенно важны из-за узкого запаса времени до травмы колена.\n\nТИПИЧНЫЕ ОШИБКИ\nФиксация ноги только руками; недооценка уязвимости колена; игнорирование свободной ноги противника; форсирование амплитуды.\n\nПРОВЕРЬ СЕБЯ\n1. Какие принципы переносятся с руки на ногу?\n2. Как устроено ущемление ахиллова сухожилия?\n3. Почему рычаг колена требует особой осторожности?\n4. Как сила ног усложняет технику фиксации?\n5. На что обращать внимание при работе с одной ногой противника?'],
['Удушающие приёмы','ПОВЫШЕННЫЙ РИСК КАК ХАРАКТЕРИСТИКА ГРУППЫ\nПотеря сознания может наступить быстрее, чем партнёр подаст сигнал остановки — это делает удушения наиболее требовательными ко всем мерам предосторожности программы одновременно.\n\nУДУШЕНИЕ ЧЕРЕЗ ПЕРЕКРЫТИЕ КРОВОСНАБЖЕНИЯ\nСдавливание сонных артерий по бокам шеи даёт быструю, но обратимую потерю сознания — отличается от воздействия на трахею спереди, которое медленнее, но рискует повредить саму трахею.\n\nЗАХВАТ С ИСПОЛЬЗОВАНИЕМ ОДЕЖДЫ\nОтворот куртки используется как рычаг воздействия на шею, распределяя усилие через ткань без прямого захвата шеи руками.\n\nОТСУТСТВИЕ ПРОМЕЖУТОЧНОГО ПРЕДУПРЕЖДЕНИЯ\nВ отличие от болевых приёмов, ощущение может смениться потерей сознания почти без выраженного дискомфорта — расчёт только на сигнал партнёра менее надёжен здесь.\n\nНЕОБХОДИМОСТЬ СТАРШЕГО НАБЛЮДАТЕЛЯ\nОтработка только двумя партнёрами без третьего, способного вмешаться быстрее реакции принимающего, сопряжена с повышенным риском.\n\nПОСТЕПЕННОСТЬ КАК СТРОЖАЙШЕЕ ТРЕБОВАНИЕ\nОт полностью безопасного положения захвата без давления к минимальному ощутимому воздействию и лишь на позднем этапе к более реалистичной, но строго ограниченной практике.\n\nВОССТАНОВЛЕНИЕ ПОСЛЕ ОТРАБОТКИ\nДаже кратковременное сдавливание требует паузы на восстановление перед следующим повторением, в отличие от более непрерывного подхода к ударной технике.\n\nСВЯЗЬ С ПРЕДЕЛАМИ САМООБУЧЕНИЯ\nЕдинственная категория техник курса, где рекомендация обратиться к очному инструктору формулируется как прямая, а не общая осторожность.\n\nТИПИЧНЫЕ ОШИБКИ\nОтработка без старшего наблюдателя; расчёт только на сигнал партнёра без учёта отсутствия предупреждения; слишком быстрый переход к реалистичному давлению; отсутствие паузы на восстановление.\n\nПРОВЕРЬ СЕБЯ\n1. Почему удушения требуют больше предосторожностей, чем любая другая техника?\n2. Чем удушение сонных артерий отличается от воздействия на трахею?\n3. Почему сигнал остановки менее надёжен для этой техники?\n4. Какая специфическая рекомендация даётся именно для удушений?\n5. Зачем нужна пауза на восстановление между повторениями?'],
['Переход от удара к клинчу','ЗАЧЕМ НУЖЕН ПЕРЕХОД МЕЖДУ ДАЛЬНОСТЯМИ\nБоец, владеющий только одной дистанцией — например, только ударами на дальней или только клинчем, — предсказуем: достаточно навязать ему невыгодную дистанцию, и вся его техника перестаёт работать. Реальное столкновение почти всегда проходит через несколько дальностей за секунды, и умение не терять контроль при смене дистанции ценнее отдельного мощного удара.\n\nТРИ КЛАССИЧЕСКИЕ ДАЛЬНОСТИ БОЯ\nДальняя (удары ногами и длинные удары руками), средняя (удары руками, локти, колени), ближняя/клинч (захват, колени, короткие удары, броски). Система, собранная в этой программе, намеренно охватывает все три, чтобы не оставлять "слепых" дистанций.\n\nМОМЕНТ ВХОДА В КЛИНЧ ПОСЛЕ УДАРА\nКлассическая ошибка — бить и оставаться на дистанции удара, ожидая ответа. Вход в клинч логичен сразу после серии, когда противник в защитной реакции (руки подняты, голова опущена, разрыв внимания на долю секунды) — именно это окно используется для сокращения дистанции.\n\nТЕХНИКА СОКРАЩЕНИЯ ДИСТАНЦИИ\nШаг вперёд с одновременным подниманием обеих рук к уровню шеи/плеч противника, контакт предплечьями раньше, чем произойдёт столкновение головами — это создаёт раннюю точку контроля ещё до завершения сближения.\n\nКОНТРОЛЬ ГОЛОВЫ КАК ПЕРВАЯ ЗАДАЧА КЛИНЧА\nЗахват шеи (одной или двумя руками) — то, ради чего вообще совершается вход, поскольку голова противника определяет положение всего его тела, и это классический принцип муай-тай клинча.\n\nСАМОСТОЯТЕЛЬНАЯ ОТРАБОТКА ПЕРЕХОДА\nРабота на мешке: серия ударов руками, затем имитация входа с обхватом мешка руками как условной "шеи", смена стойки на более узкую и низкую, характерную для клинча. Так нарабатывается моторика перехода без партнёра.\n\nТРЕБУЕТ ПАРТНЁРА ДЛЯ РЕАЛИСТИЧНОГО ЗАВЕРШЕНИЯ\nПолноценный переход с сопротивлением, борьбой за захват головы и попыткой партнёра отбить руки — только с живым партнёром; в одиночку осваивается лишь механика движения.\n\nТИПИЧНЫЕ ОШИБКИ\nВход с опущенными руками; ожидание на ударной дистанции вместо немедленного продолжения; попытка захватить сразу руки вместо шеи; слишком широкий шаг, теряющий баланс; отсутствие смены стойки при входе в клинч.\n\nПРОВЕРЬ СЕБЯ\n1. Почему важно владеть переходами между дальностями, а не только одной из них?\n2. В какой момент выгоднее всего входить в клинч после серии ударов?\n3. Что контролируется в первую очередь при входе в клинч и почему?\n4. Как отрабатывать вход в клинч в одиночку на мешке?\n5. Что именно нельзя полноценно освоить без партнёра в этой теме?'],
['Переход от клинча к броску','ЛОГИКА СМЕНЫ КЛИНЧА НА БРОСОК\nКлинч сам по себе не завершает столкновение — это позиция контроля, из которой следует либо продолжение ударов, либо перевод противника в положение, где он теряет возможность сопротивляться: на землю. Переход к броску — способ завершить эпизод в свою пользу без долгого силового противостояния в клинче.\n\nПРИЗНАКИ ГОТОВНОСТИ К БРОСКУ ИЗ КЛИНЧА\nМомент, когда вес противника смещён на одну ногу, когда он тянет в свою сторону (используется его же импульс), или когда получен контроль головы с одновременным упором в плечо/руку — это стандартные "окна" для броска из системы самбо и дзюдо-клинча.\n\nСВЯЗКА С БИОМЕХАНИКОЙ КАДОЧНИКОВА\nПринцип "не противостоять силе, а перенаправлять её" применяется именно в этой точке: рывок противника на себя не блокируется, а используется как дополнительный импульс для броска через бедро или подсечки.\n\nПОДГОТОВКА БРОСКА: ВЫВЕДЕНИЕ ИЗ РАВНОВЕСИЯ ПЕРЕД ВХОДОМ В БРОСОК\nКимпо-принцип "кузуши" (взятый как общий для борцовских систем) — прежде чем входить в бросок, равновесие противника уже должно быть подорвано хотя бы частично, иначе бросок превращается в силовое поднятие тяжести.\n\nСАМОСТОЯТЕЛЬНАЯ ОТРАБОТКА ПОДГОТОВКИ К БРОСКУ\nРабота с манекеном для бросков либо с тяжёлым мешком, подвешенным низко: захват в положении, аналогичном клинчу, отработка входа бедром/ногой под манекен без реального завершения броска — так нарабатывается вход.\n\nТРЕБУЕТ ПАРТНЁРА ДЛЯ САМОГО БРОСКА\nНастоящий бросок требует реального веса и сопротивления живого партнёра, а также умения партнёра падать (укеми) — это невозможно заменить в одиночной тренировке, только приближение к ней.\n\nТИПИЧНЫЕ ОШИБКИ\nПопытка бросить силой без предварительного нарушения равновесия; вход в бросок без контроля верхней части тела противника; резкий бросок без страховки партнёра; выбор броска без учёта стойки противника.\n\nПРОВЕРЬ СЕБЯ\n1. Зачем вообще переходить от клинча к броску, а не оставаться в клинче?\n2. Какие признаки говорят о готовности противника к броску?\n3. Как принцип Кадочникова о перенаправлении силы применяется в этом переходе?\n4. Что такое "кузуши" и почему это должно происходить раньше самого броска?\n5. Что из этой темы можно отработать в одиночку, а что нет?'],
['От броска к контролю на земле','ПОЧЕМУ БРОСОК — НЕ КОНЕЦ ЭПИЗОДА\nБросок сам по себе не гарантирует безопасность: противник на земле может продолжать сопротивляться, попытаться встать или атаковать снизу. Без немедленного перехода к контролю бросок превращается в бесполезное действие, которое лишь тратит энергию.\n\nПЕРВАЯ СЕКУНДА ПОСЛЕ ПРИЗЕМЛЕНИЯ ПРОТИВНИКА\nКлассическая ошибка — пауза после броска, чтобы "посмотреть, что получилось". Правильная последовательность: бросок и немедленное падение вместе с противником в контролирующую позицию, без разрыва контакта.\n\nБАЗОВЫЕ ПОЗИции КОНТРОЛЯ НА ЗЕМЛЕ\nВерхняя позиция (сверху, между или сбоку от ног противника), контроль корпуса весом, прижатие одной руки противника — задача не "бороться", а ограничить его подвижность с минимальными затратами силы, что прямо связано с темой базовых позиций контроля, уже пройденной ранее.\n\nПРИНЦИП САМБО: КОНТРОЛЬ ВАЖНЕЕ БОЛЕВОГО ПРИЁМА\nВ прикладном контексте самообороны важнее сначала лишить противника возможности продолжать нападение (контроль), чем сразу пытаться завершить болевым приёмом — переход к болевому делается только после устойчивого контроля.\n\nСАМОСТОЯТЕЛЬНАЯ ЧАСТЬ: ОТРАБОТКА СОБСТВЕННОГО ПАДЕНИЯ ВМЕСТЕ С БРОСКОМ\nОтработка укеми в положении "падаю вместе с воображаемым противником", контроль своего тела при приземлении сверху на условную цель (мат, манекен) — так, чтобы не терять баланс в момент завершения броска.\n\nТРЕБУЕТ ПАРТНЁРА\nРеальное сопротивление на земле, попытки встать, побороться за позицию — целиком парная работа, критически отличающаяся от работы с манекеном по степени непредсказуемости.\n\nТИПИЧНЫЕ ОШИБКИ\nПауза после броска; попытка сразу искать болевой приём без стабильного контроля; разрыв контакта с противником сразу после падения; излишнее давление весом, ведущее к потере собственного равновесия.\n\nПРОВЕРЬ СЕБЯ\n1. Почему бросок без последующего контроля малоэффективен?\n2. Что нужно делать в первую секунду после падения противника?\n3. Какой принцип самбо расставляет приоритет между контролем и болевым приёмом?\n4. Что из перехода "бросок-контроль" тренируется самостоятельно?\n5. Почему именно эта тема требует партнёра почти полностью?'],
['Комбинированные связки: удар-уход-контроль','ИДЕЯ ИНТЕГРАЦИИ ВСЕХ ДАЛЬНОСТЕЙ В ОДНУ ЛОГИКУ\nВсе предыдущие темы модуля рассматривали переходы между двумя соседними дальностями по отдельности. Эта тема объединяет их в целостную связку: удар — уход с линии атаки или клинч — завершение контролем, что отражает то, как реально развивается силовой конфликт, а не отдельные технические элементы.\n\nПРИМЕР БАЗОВОЙ СВЯЗКИ\nДжеб-кросс на дальней дистанции → шаг с уходом от встречного удара (принцип из темы "уходы с линии атаки") → вход в клинч на образовавшемся открытии → бросок через бедро → контроль сверху. Каждый элемент уже отрабатывался отдельно в программе, здесь они соединяются в цепь.\n\nПРИНЦИП "ОДНО ДЕЙСТВИЕ ГОТОВИТ СЛЕДУЮЩЕЕ"\nНи один элемент связки не выполняется как самоценный — удар создаёт открытие для входа, уход создаёт положение для клинча, клинч создаёт условие для броска. Отработка этого принципа тренирует не силу отдельного приёма, а непрерывность мышления в бою.\n\nСАМОСТОЯТЕЛЬНАЯ ОТРАБОТКА СВЯЗКИ\nПолная связка отрабатывается против мешка и в воздух (шедоу-файтинг): удары на мешке, уход в сторону, имитация захвата шеи мешка или воображаемого партнёра, имитация броска (без реального завершения) и падение в контролирующую позицию на мат. Повторяется медленно, затем в темпе.\n\nРОЛЬ ПОВТОРЕНИЯ БЕЗ ПАРТНЁРА\nИменно эта комбинированная форма лучше всего компенсирует отсутствие постоянного партнёра: она тренирует переключение между разделами системы как единый навык, даже если каждый отдельный "укол" реализма (реальный захват, реальное падение) доступен только при парной тренировке.\n\nТРЕБУЕТ ПАРТНЁРА ДЛЯ ПОЛНОЙ РЕАЛИЗАЦИИ\nСвязка с реальным сопротивлением на каждом этапе — финальная проверка усвоения всей системы, доступная только в парной работе, описанной в следующем модуле программы.\n\nТИПИЧНЫЕ ОШИБКИ\nРазрыв связки на паузы между элементами; выполнение элементов "для галочки" без реальной логики перехода; работа только над одной частью связки в ущерб остальным; потеря стойки при переходе между дальностями.\n\nПРОВЕРЬ СЕБЯ\n1. Чем комбинированная связка отличается от отработки отдельных приёмов?\n2. Приведите пример связки удар-уход-клинч-бросок-контроль.\n3. Что означает принцип "одно действие готовит следующее"?\n4. Как отрабатывать полную связку в одиночку?\n5. Что даёт эта тема для восполнения нехватки постоянного партнёра?'],
['Работа с мешком и макиварой','РОЛЬ СНАРЯДОВ В ОДИНОЧНОЙ ТРЕНИРОВКЕ\nМешок и макивара — единственные снаряды, дающие настоящее физическое сопротивление и обратную связь по силе удара без партнёра. Это отличает их от работы перед зеркалом (даёт обратную связь только по форме) и от боя с тенью (не даёт обратной связи по контакту вообще).\n\nМЕШОК: ОБЪЁМ, ВЕС, ПОДВЕСКА\nТяжёлый мешок (от 30-40 кг) подходит для силовых ударов и связок, лёгкий и подвижный — для отработки точности и реакции на движение цели. Высота подвески должна соответствовать реальному распределению зон тела: голова, корпус, бёдра — согласно ударам, изученным в программе.\n\nМАКИВАРА: ТОЧНОСТЬ И ЖЁСТКОСТЬ УДАРА\nВ отличие от мягкого мешка, макивара (жёсткая набивная доска) даёт обратную связь по правильной постановке кулака/стопы и по включению корпуса в удар — ошибка в биомеханике сразу отдаётся болью в кисти, что является встроенным самокорректирующим механизмом.\n\nСТРУКТУРА ОДИНОЧНОЙ ТРЕНИРОВКИ НА СНАРЯДЕ\nРазминка → отработка одиночных ударов на технику (медленно, с фокусом на структуру) → отработка на скорость и силу → комбинации из программы (боксёрские, тайские, дуаньда) → работа на выносливость (раунды по 2-3 минуты). Такая структура воспроизводит логику полноценного тренировочного занятия без инструктора.\n\nПЕРЕНОС ПРИНЦИПОВ РАЗНЫХ СТИЛЕЙ НА ОДИН СНАРЯД\nМешок используется для интеграции техник из разных разделов программы: боксёрские связки, тайские удары ногой/коленом/локтем, короткие удары дуаньда — все они отрабатываются на одном и том же снаряде, что помогает почувствовать разницу дистанций на практике.\n\nСАМОКОНТРОЛЬ ТЕХНИКИ БЕЗ ТРЕНЕРА\nПериодическая видеосъёмка своей работы на мешке и сравнение с эталонными видео (боксёров, тайбоксёров) — практический метод компенсации отсутствия тренера, регулярно рекомендуемый в методических материалах федераций единоборств.\n\nТИПИЧНЫЕ ОШИБКИ\nРабота только на силу без отработки техники; отсутствие разминки перед ударами по макиваре, что ведёт к травмам суставов; игнорирование защиты и передвижения при работе на мешке; чрезмерный объём работы на макиваре без постепенной адаптации кожи и костей кисти.\n\nПРОВЕРЬ СЕБЯ\n1. Чем работа на мешке отличается от работы на макиваре по типу обратной связи?\n2. Как выбрать вес и тип мешка под конкретную задачу?\n3. Опишите структуру одиночной тренировки на снаряде.\n4. Как один и тот же мешок используется для разных стилей программы?\n5. Каким способом можно контролировать свою технику без тренера?'],
['Теневой бой и работа перед зеркалом','ЗАЧЕМ НУЖЕН БОЙ С ТЕНЬЮ, ЕСЛИ ЕСТЬ МЕШОК\nБой с тенью (шедоу-файтинг) не даёт физического контакта, зато даёт то, чего не даёт мешок: полную свободу перемещения, работу с воображаемым противником, который двигается и реагирует, и возможность отрабатывать защиту и уклоны, которые на стационарном мешке отрабатывать нечем.\n\nРАБОТА ПЕРЕД ЗЕРКАЛОМ: КОНТРОЛЬ ФОРМЫ\nЗеркало даёт немедленную визуальную обратную связь о структуре стойки, симметрии ударов, положении рук в защите — то, что при работе на мешке трудно заметить самому, поскольку внимание занято снарядом.\n\nВООБРАЖАЕМЫЙ ПРОТИВНИК КАК МЕТОД\nТехнически подкованный шедоу-файтинг предполагает не размахивание руками в пустоту, а реальную визуализацию: конкретный воображаемый противник, конкретная его атака, конкретный ответ. Это связано с темой ментальной репетиции и визуализации, пройденной в модуле психологической подготовки.\n\nИНТЕГРАЦИЯ ЗАЩИТЫ И ПЕРЕДВИЖЕНИЯ\nВ отличие от работы на мешке, где основное внимание на ударе, бой с тенью — единственный способ в одиночку интегрировать защиту (блоки, уклоны), передвижение и контратаку в единый непрерывный процесс.\n\nСТРУКТУРА ТРЕНИРОВКИ ТЕНЕВОГО БОЯ\nРаунды по 2-3 минуты: первый раунд — только перемещение и дистанция, второй — добавление одиночных ударов, третий — полные комбинации с защитой и уходами, четвёртый — работа в высоком темпе для развития выносливости.\n\nИСПОЛЬЗОВАНИЕ ВИДЕОЗАПИСИ\nСъёмка теневого боя и последующий разбор — способ увидеть свои ошибки в передвижении и балансе со стороны, компенсируя отсутствие тренера, который в обычной ситуации даёт эту обратную связь вживую.\n\nТИПИЧНЫЕ ОШИБКИ\nБой с тенью без конкретного воображаемого сценария ("бой в пустоту"); работа только руками без ног и корпуса; отсутствие защитных действий в комбинациях; монотонный темп без вариативности.\n\nПРОВЕРЬ СЕБЯ\n1. Что даёт бой с тенью, чего не даёт работа на мешке?\n2. Какую обратную связь даёт зеркало и почему это важно?\n3. Что значит "технически подкованный" теневой бой?\n4. Опишите структуру тренировки по раундам.\n5. Как видеозапись помогает компенсировать отсутствие тренера?'],
['Отработка форм и одиночных комплексов','ЗНАЧЕНИЕ ФОРМАЛЬНЫХ КОМПЛЕКСОВ В СИСТЕМАХ БЕЗ ПОСТОЯННОГО ПАРТНЁРА\nТаолу (в дуаньда цюань) и аналогичные формальные последовательности в других традиционных системах существуют именно потому, что традиционные школы Восточной Азии веками решали задачу передачи и самостоятельной отработки техники без ежедневного спарринга — форма кодирует движения в воспроизводимую одиночную практику.\n\nСВЯЗЬ С ТЕМОЙ "ФОРМАЛЬНЫЕ КОМПЛЕКСЫ КОРОТКОГО УДАРА"\nЭта тема была рассмотрена в модуле дуаньда цюань как техническое содержание форм; здесь рассматривается методика их использования как основного инструмента одиночной тренировки на протяжении всего курса, а не только в разделе короткого удара.\n\nТРИ УРОВНЯ ОТРАБОТКИ ФОРМЫ\nПервый уровень — точность движений в медленном темпе (структура важнее скорости); второй — слитность и переходы между элементами без остановок; третий — вложение силы и скорости, приближающее форму к боевому применению. Пропуск первого уровня в пользу быстрой отработки — частая причина закрепления ошибок.\n\nФОРМА КАК СПОСОБ ЗАПОМИНАНИЯ ПРИНЦИПОВ БИОМЕХАНИКИ\nПомимо запоминания конкретных движений, форма закрепляет общие принципы — перенос веса, работу бёдрами (фацзинь), сохранение центра тяжести — то есть работает как обучающий инструмент, а не только как демонстрационная последовательность.\n\nСОЗДАНИЕ СОБСТВЕННЫХ КОРОТКИХ ФОРМ\nДля элементов программы, не имеющих готовой традиционной формы (например, боксёрских комбинаций), рекомендуется самостоятельно фиксировать собственные короткие последовательности из 4-6 движений и повторять их регулярно — метод переносится из традиционной практики на всю систему.\n\nОГРАНИЧЕНИЯ ФОРМ БЕЗ ПАРТНЁРА\nФорма тренирует моторику и структуру, но не даёт опыта реального сопротивления и непредсказуемости — этот пробел закрывается только в прикладном разделе с партнёром, форма не заменяет спарринг, а готовит к нему.\n\nТИПИЧНЫЕ ОШИБКИ\nПереход к скорости раньше освоения точной структуры; выполнение формы "для галочки" без понимания смысла движений; отсутствие регулярности повторения; убеждение, что освоение формы равносильно боевой готовности.\n\nПРОВЕРЬ СЕБЯ\n1. Почему традиционные системы исторически полагались на формальные комплексы?\n2. Назовите три уровня отработки формы.\n3. Что, помимо конкретных движений, закрепляет форма?\n4. Как создать собственную короткую форму для техник без готового таолу?\n5. Какой пробел форма не закрывает и почему?'],
['Общефизическая и специальная подготовка','ЗАЧЕМ НУЖНА ОФП И СФП ОТДЕЛЬНО ОТ ТЕХНИКИ\nТехнически правильное движение, выполненное без достаточной физической базы (силы, выносливости, гибкости), теряет эффективность в реальном применении — усталость разрушает технику быстрее, чем недостаток тренировок самой техники. ОФП и СФП — это база, на которой держится вся остальная программа.\n\nОБЩЕФИЗИЧЕСКАЯ ПОДГОТОВКА (ОФП)\nБазовая выносливость (бег, скакалка), общая сила (отжимания, приседания, подтягивания, планка), гибкость (растяжка). Не привязана к конкретному стилю, но необходима для качественного выполнения любой техники программы.\n\nСПЕЦИАЛЬНАЯ ФИЗИЧЕСКАЯ ПОДГОТОВКА (СФП)\nНаправлена на конкретные требования единоборств программы: взрывная сила ног для ударов ногами и бросков, сила хвата для клинча и бросковой техники, сила кора для устойчивости при контактах, скоростная выносливость для поддержания темпа боя.\n\nСВЯЗЬ СО СТРЕССОВОЙ РЕАКЦИЕЙ ОРГАНИЗМА\nТема стрессовой реакции организма в конфликте (модуль психологической подготовки) отмечает резкий скачок пульса и расход энергии в первые секунды столкновения — хорошая физическая база напрямую повышает способность действовать технически грамотно даже при высоком пульсе.\n\nПРИМЕРНАЯ СТРУКТУРА НЕДЕЛЬНОГО ЦИКЛА ОФП/СФП\n2-3 дня силовой работы (собственный вес или отягощения), 2 дня кардио/выносливости, 1-2 дня гибкости и восстановления, интегрированные с днями технической работы так, чтобы не накладывать тяжёлую физическую нагрузку на день перед сложной технической отработкой.\n\nПРИНЦИП СПЕЦИФИЧНОСТИ НАГРУЗКИ\nОФП и СФП должны соответствовать требованиям применяемых техник — например, для клинча важнее статическая сила удержания захвата, чем максимальная сила одного повторения, что определяет выбор конкретных упражнений.\n\nТИПИЧНЫЕ ОШИБКИ\nПерекос в сторону только силовой работы без выносливости или наоборот; игнорирование гибкости, ограничивающее амплитуду ударов ногами; отсутствие восстановления между тяжёлыми циклами; физическая подготовка в отрыве от технических задач конкретных разделов программы.\n\nПРОВЕРЬ СЕБЯ\n1. Почему технику нельзя тренировать в отрыве от физической подготовки?\n2. Чем ОФП отличается от СФП?\n3. Как физическая подготовка связана со стрессовой реакцией организма в конфликте?\n4. Опишите примерную структуру недельного цикла.\n5. Что означает принцип специфичности нагрузки?'],
['Поиск партнёра и организация парной тренировки','ПОЧЕМУ ЭТА ТЕМА ЗАВЕРШАЕТ ПРОГРАММУ, А НЕ ОТКРЫВАЕТ ЕЁ\nВсе разделы программы, помеченные "ТРЕБУЕТ ПАРТНЁРА", были написаны полностью — с теорией и методикой, — но их практическая реализация начинается только тогда, когда найден реальный партнёр. Эта тема — мост между одиночной теоретической/технической подготовкой и переходом к парной практике.\n\nГДЕ ИСКАТЬ ПАРТНЁРА ДЛЯ ТРЕНИРОВОК\nСекции смежных единоборств (бокс, самбо, дзюдо, муай-тай) в своём городе — даже без записи на постоянные занятия можно найти партнёра для отдельных тренировок; онлайн-сообщества практикующих систему Кадочникова; знакомые с любым борцовским или ударным опытом, готовые тренироваться по обмену.\n\nКРИТЕРИИ ВЫБОРА ПАРТНЁРА ДЛЯ БЕЗОПАСНОЙ ПРАКТИКИ\nПартнёр не обязан быть опытнее — важнее совместимость по уровню агрессии и контролю, готовность останавливаться по сигналу, отсутствие соревновательного эго, из-за которого учебная тренировка превращается в неконтролируемый спарринг.\n\nДОГОВОРЁННОСТИ ПЕРЕД НАЧАЛОМ ПАРНОЙ РАБОТЫ\nЧёткий сигнал остановки (стук по телу/полу дважды, словесное "стоп"), согласованный уровень контакта (обозначение удара / контакт в 30% силы / полный контакт — только для отдельных, заранее оговорённых элементов), обязательное наличие матов для бросковой и наземной техники.\n\nСТРУКТУРА ПЕРВЫХ СОВМЕСТНЫХ ТРЕНИРОВОК\nНачинать с тем, отмеченных "ТРЕБУЕТ ПАРТНЁРА" в порядке возрастания сложности: сначала укеми и страховка при падениях (уже частично освоенные одному), затем базовые захваты и контроли, затем броски, и только в конце — работа с сопротивлением и болевые/удушающие приёмы.\n\nСВЯЗЬ С ТЕМОЙ ТЕХНИКИ БЕЗОПАСНОСТИ ПРИ ПАРНОЙ РАБОТЕ\nВсе договорённости здесь опираются на принципы, изложенные в первой теме программы ("Техника безопасности при парной работе") — эта тема даёт организационную рамку для применения тех принципов на практике.\n\nТИПИЧНЫЕ ОШИБКИ\nНачало парной практики сразу со сложных приёмов без разминочных совместных тем; отсутствие чёткого сигнала остановки перед началом; выбор партнёра с несовместимым уровнем агрессии; тренировка без матов там, где они необходимы.\n\nПРОВЕРЬ СЕБЯ\n1. Почему эта тема логично завершает программу, а не открывает её?\n2. Где реалистично искать партнёра для тренировок?\n3. Какие критерии важнее опыта партнёра?\n4. Какие договорённости нужно установить перед первой парной тренировкой?\n5. В каком порядке вводить парные темы программы?'],
['Базовые сценарии самообороны','ОТ ОТДЕЛЬНЫХ ТЕХНИК К ЦЕЛОСТНЫМ СЦЕНАРИЯМ\nВсе предыдущие темы программы — это строительные блоки: удары, броски, контроли, переходы. Сценарная отработка объединяет их в реалистичные, заранее оговорённые ситуации, максимально приближенные к типичным условиям бытового или уличного конфликта, но выполняемые в контролируемом, безопасном формате.\n\nТИПОВЫЕ СЦЕНАРИИ ДЛЯ ОТРАБОТКИ\nЗахват за одежду спереди, захват сзади (за корпус или шею), попытка ударить в клинче, попытка повалить на землю, атака в замкнутом пространстве (у стены, в углу) — сценарии подбираются по частоте встречаемости в реальных конфликтах, а не по зрелищности.\n\nПРИНЦИП ФИКСИРОВАННОГО СЦЕНАРИЯ НА РАННЕМ ЭТАПЕ\nНа старте партнёр выполняет заранее оговорённое действие (например, всегда один и тот же захват) в среднем темпе, а обороняющийся отрабатывает связку ответа. Это позволяет наработать моторику реакции прежде, чем добавлять непредсказуемость.\n\nПОСТЕПЕННОЕ ДОБАВЛЕНИЕ ВАРИАТИВНОСТИ\nПосле уверенного освоения фиксированного сценария партнёр начинает менять детали (сила захвата, направление, скорость) в рамках того же типа атаки — переходная ступень к теме "работа с обозначенным сопротивлением".\n\nИНТЕГРАЦИЯ ПСИХОЛОГИЧЕСКОЙ ПОДГОТОВКИ В СЦЕНАРИИ\nСценарии — подходящее место для практического применения тем модуля психологической подготовки: управления уровнем возбуждения, борьбы с тоннельным зрением — поскольку неожиданный (пусть и оговорённый по типу) контакт партнёра вызывает частичную стрессовую реакцию, аналогичную реальной.\n\nОБЯЗАТЕЛЬНОСТЬ РАЗБОРА ПОСЛЕ СЦЕНАРИЯ\nПосле каждой отработки — короткое обсуждение с партнёром: что сработало, где возникла пауза или растерянность, что нужно повторить медленнее. Разбор — не менее важная часть тренировки, чем само выполнение.\n\nТИПИЧНЫЕ ОШИБКИ\nПереход к вариативным сценариям слишком рано; отсутствие разбора после отработки; использование сценариев только для отработки "красивых" приёмов без связи с реалистичностью атаки; игнорирование психологического компонента сценария.\n\nПРОВЕРЬ СЕБЯ\n1. Чем сценарная отработка отличается от отработки отдельных приёмов?\n2. Назовите несколько типовых сценариев для отработки.\n3. Как строится фиксированный сценарий на раннем этапе?\n4. Как психологическая подготовка применяется в сценариях?\n5. Почему разбор после сценария обязателен?'],
['Работа с обозначенным сопротивлением','ЧТО ТАКОЕ ОБОЗНАЧЕННОЕ СОПРОТИВЛЕНИЕ\nПромежуточная ступень между полностью кооперативной парной отработкой (партнёр не сопротивляется) и свободным спаррингом (партнёр сопротивляется в полную силу). Партнёр создаёт реальное, но дозированное и заранее согласованное по интенсивности сопротивление — например, 30-50% от максимума.\n\nЗАЧЕМ НУЖНА ЭТА ПРОМЕЖУТОЧНАЯ СТУПЕНЬ\nПрямой переход от кооперативной отработки к полному спаррингу приводит к тому, что наработанная в одиночку и с кооперативным партнёром техника "рассыпается" при столкновении с реальным сопротивлением — обозначенное сопротивление даёт опыт борьбы за приём при контролируемом уровне риска травм.\n\nПРИМЕНЕНИЕ К РАЗНЫМ РАЗДЕЛАМ ПРОГРАММЫ\nВ бросковой технике — партнёр слегка сопротивляется входу и старается сохранить равновесие; в клинче — партнёр борется за захват шеи, но не бьёт в полную силу; в болевых приёмах — партнёр сопротивляется до последнего момента, но простукивает (сигнал остановки) при реальной боли, а не терпит её.\n\nПРИНЦИП ПОСТЕПЕННОГО НАРАЩИВАНИЯ ИНТЕНСИВНОСТИ\nНачинать с 20-30% сопротивления и повышать его от тренировки к тренировке только после уверенного выполнения приёма на текущем уровне — резкий скачок интенсивности является наиболее частой причиной травм в парной практике боевых искусств.\n\nРОЛЬ ОБРАТНОЙ СВЯЗИ ОТ ПАРТНЁРА\nВ отличие от кооперативной практики, партнёр в обозначенном сопротивлении даёт честную информацию о том, действительно ли приём выведен из равновесия/техника работает, а не выполняется "потому что так было оговорено" — это первый настоящий тест функциональности навыка.\n\nСВЯЗЬ С ОГРАНИЧЕНИЯМИ ОДИНОЧНОЙ ТРЕНИРОВКИ\nТема прямо закрывает тот пробел, о котором говорилось во всех предыдущих "одиночных" темах программы: борьба за равновесие, за захват, за позицию контроля принципиально не может быть смоделирована без второго человека, создающего непредсказуемое, но управляемое противодействие.\n\nТИПИЧНЫЕ ОШИБКИ\nСлишком быстрое повышение интенсивности сопротивления; партнёр, который либо совсем не сопротивляется, либо сразу сопротивляется в полную силу, минуя промежуточный этап; отсутствие честной обратной связи о том, сработал ли приём.\n\nПРОВЕРЬ СЕБЯ\n1. Чем обозначенное сопротивление отличается от кооперативной отработки и от спарринга?\n2. Зачем нужна эта промежуточная ступень?\n3. Приведите пример применения обозначенного сопротивления в бросковой технике.\n4. Как правильно наращивать интенсивность сопротивления?\n5. Какой пробел одиночной тренировки закрывает именно эта тема?'],
['Пределы самостоятельного освоения и когда нужен инструктор','ЧЕСТНАЯ ОЦЕНКА ГРАНИЦ ЭТОЙ ПРОГРАММЫ\nПрограмма построена так, чтобы дать максимум возможного без постоянного тренера: теорию, одиночную техническую базу, методику парной работы при появлении партнёра. Но у самостоятельного освоения боевых систем есть объективные пределы, и заключительная тема программы — не техника, а честная карта этих пределов.\n\nЧТО НАДЁЖНО ОСВАИВАЕТСЯ САМОСТОЯТЕЛЬНО\nБазовая ударная техника (постановка, техничность движения), общефизическая и специальная подготовка, формы и одиночные комплексы, теоретическое понимание принципов (биомеханика, тактика, психология) — все эти элементы подтверждённо поддаются самостоятельному качественному освоению по видео-эталонам и структурированной практике.\n\nЧТО ПРИНЦИПИАЛЬНО ТРЕБУЕТ ЖИВОГО ОППОНЕНТА С РАСТУЩЕЙ КВАЛИФИКАЦИЕЙ\nСвободный спарринг с реальной непредсказуемостью, тонкая коррекция биомеханики движения (то, что тренер замечает со стороны и что невозможно увидеть в себе даже на видео), приёмы с высоким риском травмы при неправильном выполнении (удушающие, некоторые броски) — здесь самостоятельная практика имеет потолок.\n\nСИГНАЛЫ, ЧТО ПОРА ИСКАТЬ ИНСТРУКТОРА ИЛИ СЕКЦИЮ\nПлато в технике, которое не удаётся преодолеть по видео-материалам; повторяющиеся мелкие травмы, указывающие на скрытую ошибку в биомеханике; желание перейти к соревновательной практике; ощущение, что дальнейшее самостоятельное развитие в конкретном разделе (например, борьба) исчерпало себя.\n\nКАК ИСПОЛЬЗОВАТЬ ЭТУ ПРОГРАММУ ПРИ ПЕРЕХОДЕ В СЕКЦИЮ\nПройденная теоретическая база и наработанная физическая форма дают заметное преимущество новичку в любой секции — время не тратится на объяснение базовых принципов и постановку общей физической готовности, инструктор сразу может работать над качеством техники и спаррингом.\n\nРИСК ПЕРЕОЦЕНКИ СОБСТВЕННОГО УРОВНЯ\nУверенное владение формой и техникой на снаряде не равно готовности к реальному применению против сопротивляющегося противника — этот разрыв между "выглядит правильно" и "работает под давлением" — главная причина, по которой программа настойчиво разделяет одиночную и парную части на всём протяжении курса.\n\nТИПИЧНЫЕ ОШИБКИ\nПереоценка своего уровня после освоения только одиночной части программы; отказ от поиска инструктора из-за ложного ощущения самодостаточности; попытка самостоятельно "изобрести" технику там, где нужна коррекция специалиста; страх перехода в секцию из-за отсутствия предварительной подготовки (хотя эта программа как раз её даёт).\n\nПРОВЕРЬ СЕБЯ\n1. Какие элементы программы надёжно осваиваются самостоятельно?\n2. Что принципиально требует живого оппонента растущей квалификации?\n3. Какие сигналы говорят, что пора искать инструктора?\n4. Как пройденная программа помогает при переходе в секцию?\n5. В чём заключается риск переоценки собственного уровня после одиночной подготовки?']
];
